/**
 * Mock传感器数据生成器
 */
class SensorMock {
  constructor() {
    /** @type {string|null} 当前激活的场景名称 */
    this.currentScenario = null
    /** @type {Object|null} 当前场景配置 */
    this.scenarioConfig = null
    /** @type {number} 当前序列索引 */
    this.sequenceIndex = 0
    /** @type {number} 当前序列内已过时间（秒） */
    this.elapsedInSegment = 0
    /** @type {Function|null} 数据回调 */
    this.onDataCallback = null
    /** @type {number|null} 定时器ID */
    this.timerId = null
    /** @type {number} 采样间隔（毫秒） */
    this.sampleInterval = 50 // 默认20Hz
    /** @type {number} 起始时间戳 */
    this.startTime = 0
  }

  /**
   * 注入Mock场景
   * @param {string} scenarioName - 场景名称
   * @returns {boolean} 是否成功注入
   */
  injectScenario(scenarioName) {
    const scenario = MOCK_SCENARIOS[scenarioName]
    if (!scenario) {
      console.error(`[SensorMock] Unknown scenario: ${scenarioName}`)
      return false
    }

    this.currentScenario = scenarioName
    this.scenarioConfig = scenario
    this.sequenceIndex = 0
    this.elapsedInSegment = 0
    this.startTime = Date.now()

    console.log(`[SensorMock] Injected scenario: ${scenario.name}`)
    return true
  }

  /**
   * 获取所有可用场景列表
   * @returns {Array<{name: string, description: string, duration: number}>}
   */
  getAvailableScenarios() {
    return Object.entries(MOCK_SCENARIOS).map(([key, scenario]) => ({
      id: key,
      name: scenario.name,
      description: scenario.description,
      duration: scenario.totalDuration,
    }))
  }

  /**
   * 设置采样间隔
   * @param {number} intervalMs - 采样间隔（毫秒）
   */
  setSampleInterval(intervalMs) {
    if (intervalMs > 0) {
      this.sampleInterval = intervalMs
    }
  }

  /**
   * 启动Mock数据流
   * @param {Function} callback - 数据回调 (data) => {}
   *   data格式: { timestamp, acc: {x,y,z}, gyro: {x,y,z}, posture: string }
   */
  startStream(callback) {
    if (!this.currentScenario) {
      console.error('[SensorMock] No scenario injected')
      return
    }

    this.onDataCallback = callback

    // 启动定时器，按采样间隔输出数据
    this.timerId = setInterval(() => {
      this._generateSample()
    }, this.sampleInterval)

    console.log(`[SensorMock] Stream started, interval: ${this.sampleInterval}ms`)
  }

  /**
   * 停止Mock数据流
   */
  stopStream() {
    if (this.timerId) {
      clearInterval(this.timerId)
      this.timerId = null
    }
    this.onDataCallback = null
    console.log('[SensorMock] Stream stopped')
  }

  /**
   * 生成单个采样点数据
   * @private
   */
  _generateSample() {
    if (!this.scenarioConfig || !this.onDataCallback) return

    const sequence = this.scenarioConfig.dataSequence
    if (this.sequenceIndex >= sequence.length) {
      // 场景结束，循环播放
      this.sequenceIndex = 0
      this.elapsedInSegment = 0
      console.log('[SensorMock] Scenario looped')
    }

    const segment = sequence[this.sequenceIndex]
    const sampleDurationMs = this.sampleInterval / 1000 // 转换为秒

    // 生成传感器数据
    const data = this._interpolateSegment(segment, sampleDurationMs)

    // 输出数据
    this.onDataCallback(data)

    // 更新时间
    this.elapsedInSegment += sampleDurationMs

    // 检查是否进入下一个片段
    if (this.elapsedInSegment >= segment.duration) {
      this.sequenceIndex++
      this.elapsedInSegment = 0
    }
  }

  /**
   * 根据片段配置插值生成传感器数据
   * @private
   * @param {Object} segment - 片段配置
   * @param {number} timeOffset - 时间偏移（秒）
   * @returns {Object} 传感器数据
   */
  _interpolateSegment(segment, timeOffset) {
    const timestamp = Date.now()

    // 生成加速度数据（基于方差）
    const acc = this._generateAccData(segment.accVar, segment.type)

    // 生成陀螺仪数据（基于俯仰角）
    const gyro = this._generateGyroData(segment.gyroPitch, segment.asymmetry)

    return {
      timestamp,
      acc,
      gyro,
      posture: segment.type,
      // Mock元数据
      _mock: {
        scenario: this.currentScenario,
        segmentIndex: this.sequenceIndex,
        segmentType: segment.type,
      },
    }
  }

  /**
   * 生成加速度数据
   * @private
   * @param {number} variance - 目标方差
   * @param {string} postureType - 体态类型
   * @returns {{x: number, y: number, z: number}}
   */
  _generateAccData(variance, postureType) {
    // 基础重力分量
    let x = 0, y = 0, z = -9.8

    // 根据体态类型调整基础值
    if (postureType === POSTURE_TYPE.FORWARD_TILT) {
      // 低头时z轴绝对值减小
      z = -6.5 + (Math.random() - 0.5) * 0.5
      x = (Math.random() - 0.5) * 0.3
    } else if (postureType === POSTURE_TYPE.CROSS_LEG) {
      // 跷二郎腿时x轴偏移
      x = 2.5 + (Math.random() - 0.5) * 0.4
      z = -9.2 + (Math.random() - 0.5) * 0.3
    } else if (postureType === POSTURE_TYPE.WALKING) {
      // 行走时有明显运动
      x = (Math.random() - 0.5) * 4
      y = (Math.random() - 0.5) * 3
      z = -9.8 + (Math.random() - 0.5) * 2
    } else {
      // 正常/久坐：添加基于方差的噪声
      const noiseScale = Math.sqrt(variance) * 10
      x = (Math.random() - 0.5) * noiseScale
      y = (Math.random() - 0.5) * noiseScale
      z = -9.8 + (Math.random() - 0.5) * noiseScale
    }

    return {
      x: Math.round(x * 1000) / 1000,
      y: Math.round(y * 1000) / 1000,
      z: Math.round(z * 1000) / 1000,
    }
  }

  /**
   * 生成陀螺仪数据
   * @private
   * @param {number} pitch - 俯仰角均值（度）
   * @param {number} asymmetry - 不对称系数
   * @returns {{x: number, y: number, z: number}}
   */
  _generateGyroData(pitch, asymmetry) {
    // 俯仰角转换为弧度/秒（简化模型）
    const pitchRad = (pitch * Math.PI) / 180

    let x = 0, y = 0, z = 0

    // 主要俯仰运动
    y = pitchRad + (Math.random() - 0.5) * 0.1

    // 如果有不对称系数，添加周期性振荡
    if (asymmetry && asymmetry > 0.2) {
      const t = Date.now() / 1000
      const freq = 0.5 + asymmetry * 0.5 // 0.5-1 Hz
      x = Math.sin(2 * Math.PI * freq * t) * asymmetry * 0.5
      z = Math.cos(2 * Math.PI * freq * t * 0.7) * asymmetry * 0.3
    }

    return {
      x: Math.round(x * 1000) / 1000,
      y: Math.round(y * 1000) / 1000,
      z: Math.round(z * 1000) / 1000,
    }
  }

  /**
   * 获取当前场景进度
   * @returns {{ current: number, total: number, percent: number }}
   */
  getProgress() {
    if (!this.scenarioConfig) {
      return { current: 0, total: 0, percent: 0 }
    }

    const elapsed = (Date.now() - this.startTime) / 1000
    const total = this.scenarioConfig.totalDuration

    return {
      current: Math.round(elapsed),
      total,
      percent: Math.min(100, Math.round((elapsed / total) * 100)),
    }
  }
}

export { MOCK_SCENARIOS, SensorMock }
export default SensorMock

/**
 * sensor-interface.js - 传感器抽象层统一接口
 *
 * 定义所有传感器驱动必须实现的接口：
 * - startSampling(config): 开始采样
 * - stopSampling(): 停止采样
 * - onData(callback): 注册数据回调
 * - getCurrentMode(): 获取当前采样模式
 *
 * 原始传感器数据禁止直接暴露给上层，必须通过接口包装后输出
 *
 * @module sensors/sensor-interface
 */

import { SAMPLING_STRATEGY, DEFAULT_STRATEGY, getSamplingInterval } from '../common/constants/sampling-config'

/**
 * 传感器数据格式
 * @typedef {Object} SensorData
 * @property {number} timestamp - 时间戳（设备本地时间）
 * @property {Object} acc - 加速度数据
 * @property {number} acc.x - X轴加速度 (m/s²)
 * @property {number} acc.y - Y轴加速度 (m/s²)
 * @property {number} acc.z - Z轴加速度 (m/s²)
 * @property {Object} gyro - 陀螺仪数据
 * @property {number} gyro.x - X轴角速度 (rad/s)
 * @property {number} gyro.y - Y轴角速度 (rad/s)
 * @property {number} gyro.z - Z轴角速度 (rad/s)
 * @property {number} [hr] - 心率 (bpm)
 */

/**
 * 传感器抽象基类
 * 所有传感器驱动必须继承此类并实现抽象方法
 */
class SensorInterface {
  /**
   * @param {string} sensorType - 传感器类型 'accelerometer'|'gyroscope'|'heartRate'
   */
  constructor(sensorType) {
    if (new.target === SensorInterface) {
      throw new Error('SensorInterface is abstract and cannot be instantiated directly')
    }

    /** @type {string} 传感器类型 */
    this.sensorType = sensorType

    /** @type {string} 当前采样策略 */
    this.currentMode = SAMPLING_STRATEGY.NIGHT

    /** @type {Function|null} 数据回调 */
    this.dataCallback = null

    /** @type {boolean} 是否正在采样 */
    this.isSampling = false

    /** @type {boolean} 是否为Mock模式 */
    this.isMockMode = false

    /** @type {Object|null} Mock数据源 */
    this.mockSource = null
  }

  /**
   * 开始采样
   * @param {Object} config - 采样配置
   * @param {string} config.strategy - 采样策略
   * @param {boolean} [config.mockMode=false] - 是否使用Mock模式
   * @param {Object} [config.mockSource] - Mock数据源
   * @throws {Error} 如果未实现此方法
   */
  startSampling(config) {
    throw new Error('startSampling() must be implemented by subclass')
  }

  /**
   * 停止采样
   * @throws {Error} 如果未实现此方法
   */
  stopSampling() {
    throw new Error('stopSampling() must be implemented by subclass')
  }

  /**
   * 注册数据回调
   * @param {Function} callback - 回调函数 (data: SensorData) => void
   */
  onData(callback) {
    this.dataCallback = callback
  }

  /**
   * 获取当前采样模式
   * @returns {string} 采样策略枚举值
   */
  getCurrentMode() {
    return this.currentMode
  }

  /**
   * 获取当前采样间隔
   * @returns {number} 采样间隔（毫秒）
   */
  getSamplingInterval() {
    return getSamplingInterval(this.currentMode, this.sensorType)
  }

  /**
   * 检查是否正在采样
   * @returns {boolean}
   */
  isRunning() {
    return this.isSampling
  }

  /**
   * 输出数据给上层（内部使用）
   * @protected
   * @param {Object} rawData - 原始传感器数据
   */
  _emitData(rawData) {
    if (!this.dataCallback) return

    // 包装数据，确保格式统一
    const wrappedData = this._wrapData(rawData)
    this.dataCallback(wrappedData)
  }

  /**
   * 包装原始数据为统一格式（子类可重写）
   * @protected
   * @param {Object} rawData - 原始数据
   * @returns {Object} 包装后的数据
   */
  _wrapData(rawData) {
    return {
      timestamp: rawData.timestamp || Date.now(),
      ...rawData,
    }
  }

  /**
   * 切换到Mock模式
   * @param {Object} mockSource - Mock数据源
   */
  enableMockMode(mockSource) {
    this.isMockMode = true
    this.mockSource = mockSource
    console.log(`[${this.sensorType}] Mock mode enabled`)
  }

  /**
   * 禁用Mock模式
   */
  disableMockMode() {
    this.isMockMode = false
    this.mockSource = null
    console.log(`[${this.sensorType}] Mock mode disabled`)
  }
}

export { SensorInterface, getSamplingInterval }
export default SensorInterface

/**
 * acc-driver.js - 加速度计驱动
 *
 * 实现加速度计传感器的采样控制：
 * - 支持真实传感器调用（OpenVela系统API）
 * - 支持Mock模式切换
 * - 数据格式：{ timestamp, acc: {x, y, z} }
 *
 * @module sensors/acc-driver
 */

import sensor from '@system.sensor'
import { SensorInterface } from './sensor-interface'
import { SAMPLING_STRATEGY, getSamplingInterval } from '../common/constants/sampling-config'

/**
 * 加速度计驱动类
 * @extends SensorInterface
 */
class AccDriver extends SensorInterface {
  constructor() {
    super('accelerometer')

    /** @type {number|null} 真实传感器订阅ID */
    this.subscriptionId = null

    /** @type {number|null} Mock模式定时器ID */
    this.mockTimerId = null
  }

  /**
   * 开始采样
   * @param {Object} config - 采样配置
   * @param {string} config.strategy - 采样策略
   * @param {boolean} [config.mockMode=false] - 是否使用Mock模式
   * @param {Object} [config.mockSource] - Mock数据源（SensorMock实例）
   * @returns {boolean} 是否成功启动
   */
  startSampling(config) {
    if (this.isSampling) {
      console.warn('[AccDriver] Already sampling, stopping first')
      this.stopSampling()
    }

    const { strategy, mockMode = false, mockSource = null } = config

    this.currentMode = strategy
    this.isMockMode = mockMode
    this.mockSource = mockSource

    const interval = getSamplingInterval(strategy, 'accelerometer')

    // 停止采样模式
    if (strategy === SAMPLING_STRATEGY.NIGHT || interval === 0) {
      console.log('[AccDriver] Night mode, sampling disabled')
      return true
    }

    if (mockMode && mockSource) {
      return this._startMockSampling(interval)
    } else {
      return this._startRealSampling(interval)
    }
  }

  /**
   * 停止采样
   * @returns {boolean} 是否成功停止
   */
  stopSampling() {
    if (!this.isSampling) return true

    // 停止Mock模式
    if (this.mockTimerId) {
      clearInterval(this.mockTimerId)
      this.mockTimerId = null
    }

    // 停止真实传感器
    if (this.subscriptionId) {
      try {
        sensor.unsubscribeAccelerometer()
        this.subscriptionId = null
      } catch (e) {
        console.error('[AccDriver] Unsubscribe error:', e)
      }
    }

    this.isSampling = false
    console.log('[AccDriver] Stopped')
    return true
  }

  /**
   * 启动真实传感器采样
   * @private
   * @param {number} intervalMs - 采样间隔（毫秒）
   * @returns {boolean}
   */
  _startRealSampling(intervalMs) {
    try {
      sensor.subscribeAccelerometer({
        callback: (data) => {
          this._onRealData(data)
        },
        fail: (data, code) => {
          console.error('[AccDriver] Subscribe fail:', code)
          this.isSampling = false
        },
      })

      this.isSampling = true
      console.log(`[AccDriver] Real sampling started, interval: ${intervalMs}ms`)
      return true
    } catch (e) {
      console.error('[AccDriver] Start error:', e)
      return false
    }
  }

  /**
   * 启动Mock模式采样
   * @private
   * @param {number} intervalMs - 采样间隔（毫秒）
   * @returns {boolean}
   */
  _startMockSampling(intervalMs) {
    if (!this.mockSource) {
      console.error('[AccDriver] No mock source')
      return false
    }

    // 设置Mock采样间隔
    this.mockSource.setSampleInterval(intervalMs)

    // 注册Mock数据回调
    this.mockSource.onDataCallback = (mockData) => {
      this._onMockData(mockData)
    }

    this.isSampling = true
    console.log(`[AccDriver] Mock sampling started, interval: ${intervalMs}ms`)
    return true
  }

  /**
   * 处理真实传感器数据
   * @private
   * @param {Object} data - 原始传感器数据 { x, y, z }
   */
  _onRealData(data) {
    // 包装数据并输出
    this._emitData({
      timestamp: Date.now(),
      acc: {
        x: data.x,
        y: data.y,
        z: data.z,
      },
    })
  }

  /**
   * 处理Mock数据
   * @private
   * @param {Object} mockData - Mock数据
   */
  _onMockData(mockData) {
    // 仅输出加速度数据部分
    this._emitData({
      timestamp: mockData.timestamp,
      acc: mockData.acc,
    })
  }

  /**
   * 重置驱动状态
   */
  reset() {
    this.stopSampling()
    this.currentMode = SAMPLING_STRATEGY.NIGHT
    this.dataCallback = null
  }
}

