export default PostureClassifier

/**
 * confidence-filter.js - 多帧确认与置信度过滤
 *
 * 实现多帧确认机制：连续3帧（约1秒）置信度均>0.8才确认异常。
 * 若置信度低于0.6，直接判定为NORMAL，不进入确认流程。
 *
 * @module core/confidence-filter
 */

import { POSTURE_TYPE } from '../common/constants/postures'

/**
 * 过滤结果结构
 * @typedef {Object} FilterResult
 * @property {boolean} confirmed - 是否确认异常
 * @property {string} posture - 体态类型
 * @property {number} confidence - 置信度 (0-1)
 * @property {number} duration - 持续时间（秒）
 * @property {number} severity - 严重程度 (1-3)
 * @property {string} detail - 详细描述
 */

class ConfidenceFilter {
  /**
   * @param {Object} options - 配置选项
   * @param {number} [options.confirmFrames=3] - 确认所需连续帧数
   * @param {number} [options.highConfidence=0.8] - 高置信度阈值
   * @param {number} [options.lowConfidence=0.6] - 低置信度阈值
   */
  constructor(options = {}) {
    /** @type {number} 确认所需连续帧数 */
    this.confirmFrames = options.confirmFrames || 3

    /** @type {number} 高置信度阈值 */
    this.highConfidence = options.highConfidence || 0.8

    /** @type {number} 低置信度阈值 */
    this.lowConfidence = options.lowConfidence || 0.6

    /** @type {Array} 历史分类结果缓冲区 */
    this.historyBuffer = []

    /** @type {number} 历史缓冲区最大长度 */
    this.maxHistorySize = 10

    /** @type {Object|null} 当前确认的异常体态 */
    this.confirmedAbnormal = null

    /** @type {number} 异常开始时间戳 */
    this.abnormalStartTime = 0

    /** @type {number} 帧间隔（秒） */
    this.frameInterval = 0.02 // 50Hz = 0.02s
  }

  /**
   * 输入分类结果并进行过滤
   * @param {Object} classification - 分类器输出 { posture, confidence, severity, detail, metrics }
   * @returns {FilterResult} 过滤结果
   */
  filter(classification) {
    const { posture, confidence, severity, detail, metrics } = classification

    // 添加到历史缓冲区
    this._addToHistory(classification)

    // 1. 低置信度直接判定为NORMAL
    if (confidence < this.lowConfidence) {
      this._resetAbnormal()
      return this._createResult(false, POSTURE_TYPE.NORMAL, confidence, 0, 1, '置信度不足')
    }

    // 2. 正常体态，重置异常状态
    if (posture === POSTURE_TYPE.NORMAL || posture === POSTURE_TYPE.WALKING) {
      this._resetAbnormal()
      return this._createResult(false, posture, confidence, 0, severity, detail)
    }

    // 3. 异常体态，检查是否需要多帧确认
    const isSameAbnormal = this.confirmedAbnormal &&
      this.confirmedAbnormal.posture === posture

    if (isSameAbnormal) {
      // 同一异常持续中
      const duration = this._calcDuration()
      const confirmed = this._checkConfirmation()

      if (confirmed) {
        return this._createResult(true, posture, confidence, duration, severity, detail)
      } else {
        return this._createResult(false, posture, confidence, duration, severity, `等待确认: ${detail}`)
      }
    } else {
      // 新的异常类型
      this._startAbnormal(posture, confidence, severity, detail, metrics)
      const duration = this.frameInterval

      // 检查是否立即确认（置信度很高时可以快速确认）
      if (confidence >= 0.9 && this._checkQuickConfirm(posture)) {
        return this._createResult(true, posture, confidence, duration, severity, detail)
      }

      return this._createResult(false, posture, confidence, duration, severity, `检测到: ${detail}`)
    }
  }

  /**
   * 检查多帧确认
   * @private
   * @returns {boolean} 是否确认
   */
  _checkConfirmation() {
    const recentFrames = this.historyBuffer.slice(-this.confirmFrames)

    // 检查最近N帧是否都是同一异常且置信度达标
    if (recentFrames.length < this.confirmFrames) {
      return false
    }

    return recentFrames.every(frame =>
      frame.posture === this.confirmedAbnormal.posture &&
      frame.confidence >= this.highConfidence
    )
  }

  /**
   * 快速确认检查（高置信度情况）
   * @private
   * @param {string} posture - 体态类型
   * @returns {boolean} 是否快速确认
   */
  _checkQuickConfirm(posture) {
    // 检查最近2帧是否都是同一异常
    const recentFrames = this.historyBuffer.slice(-2)
    return recentFrames.length >= 2 &&
      recentFrames.every(frame => frame.posture === posture)
  }

  /**
   * 开始新的异常记录
   * @private
   * @param {string} posture - 体态类型
   * @param {number} confidence - 置信度
   * @param {number} severity - 严重程度
   * @param {string} detail - 详细描述
   * @param {Object} metrics - 分类指标
   */
  _startAbnormal(posture, confidence, severity, detail, metrics) {
    this.confirmedAbnormal = {
      posture,
      confidence,
      severity,
      detail,
      metrics,
    }
    this.abnormalStartTime = Date.now()
  }

  /**
   * 重置异常状态
   * @private
   */
  _resetAbnormal() {
    this.confirmedAbnormal = null
    this.abnormalStartTime = 0
  }

  /**
   * 计算异常持续时间
   * @private
   * @returns {number} 持续时间（秒）
   */
  _calcDuration() {
    if (this.abnormalStartTime === 0) return 0
    return (Date.now() - this.abnormalStartTime) / 1000
  }

  /**
   * 添加到历史缓冲区
   * @private
   * @param {Object} classification - 分类结果
   */
  _addToHistory(classification) {
    this.historyBuffer.push({
      posture: classification.posture,
      confidence: classification.confidence,
      timestamp: Date.now(),
    })

    // 限制缓冲区大小
    if (this.historyBuffer.length > this.maxHistorySize) {
      this.historyBuffer.shift()
    }
  }

  /**
   * 创建过滤结果对象
   * @private
   * @param {boolean} confirmed - 是否确认
   * @param {string} posture - 体态类型
   * @param {number} confidence - 置信度
   * @param {number} duration - 持续时间
   * @param {number} severity - 严重程度
   * @param {string} detail - 详细描述
   * @returns {FilterResult}
   */
  _createResult(confirmed, posture, confidence, duration, severity, detail) {
    return {
      confirmed,
      posture,
      confidence: Math.round(confidence * 100) / 100,
      duration: Math.round(duration * 10) / 10,
      severity,
      detail,
    }
  }

  /**
   * 获取当前状态
   * @returns {{hasAbnormal: boolean, abnormalType: string|null, duration: number}}
   */
  getStatus() {
    return {
      hasAbnormal: this.confirmedAbnormal !== null,
      abnormalType: this.confirmedAbnormal ? this.confirmedAbnormal.posture : null,
      duration: this._calcDuration(),
    }
  }

  /**
   * 重置过滤器
   */
  reset() {
    this.historyBuffer = []
    this.confirmedAbnormal = null
    this.abnormalStartTime = 0
  }
}

export { ConfidenceFilter }
export default ConfidenceFilter

/**
 * alert-trigger.js - 分级提醒触发器
 *
 * 根据体态异常的严重程度触发不同级别的提醒：
 * - 轻微（severity=1）：单次短震动（50ms），30分钟内最多1次
 * - 中度（severity=2）：震动（100ms）+ 呼吸灯事件，15分钟内最多1次
 * - 严重（severity=3）：震动（200ms）+ 弹窗事件，即时触发但每小时最多2次
 *
 * @module core/alert-trigger
 */

import vibrator from '@system.vibrator'
import prompt from '@system.prompt'

/**
 * 提醒级别配置
 * @readonly
 */
const ALERT_LEVELS = {
  1: {
    name: '轻微',
    vibrationDuration: 50,
    cooldownMs: 30 * 60 * 1000, // 30分钟
    maxPerPeriod: 1,
    icon: '💡',
  },
  2: {
    name: '中度',
    vibrationDuration: 100,
    cooldownMs: 15 * 60 * 1000, // 15分钟
    maxPerPeriod: 1,
    icon: '⚠️',
  },
  3: {
    name: '严重',
    vibrationDuration: 200,
    cooldownMs: 60 * 60 * 1000, // 1小时
    maxPerPeriod: 2,
    icon: '🚨',
  },
}

/**
 * 体态类型中文名
 * @readonly
 */
const POSTURE_NAMES = {
  sedentary: '久坐',
  forward_tilt: '低头前倾',
  cross_leg: '跷二郎腿',
}

class AlertTrigger {
  constructor() {
    /** @type {Object} 各级别最后触发时间 */
    this.lastTriggerTime = {
      1: 0,
      2: 0,
      3: 0,
    }

    /** @type {Object} 各级别触发计数（用于每周期限制） */
    this.triggerCount = {
      1: 0,
      2: 0,
      3: 0,
    }

    /** @type {Object} 各级别计数重置时间 */
    this.countResetTime = {
      1: 0,
      2: 0,
      3: 0,
    }

    /** @type {Function|null} 事件回调 */
    this.onEvent = null

    /** @type {boolean} 是否静音模式 */
    this.isMuted = false
  }

  /**
   * 触发提醒
   * @param {Object} filterResult - 过滤器输出 { confirmed, posture, confidence, duration, severity, detail }
   * @returns {boolean} 是否成功触发
   */
  trigger(filterResult) {
    const { confirmed, posture, severity, duration, detail } = filterResult

    // 未确认的异常不触发提醒
    if (!confirmed) return false

    // 检查是否在冷却期
    if (this._isInCooldown(severity)) {
      return false
    }

    // 检查是否超过每周期最大次数
    if (this._isOverLimit(severity)) {
      return false
    }

    // 执行提醒
    const levelConfig = ALERT_LEVELS[severity]
    const postureName = POSTURE_NAMES[posture] || '未知'

    console.log(`[AlertTrigger] Triggering level ${severity}: ${postureName}`)

    // 1. 震动提醒
    if (!this.isMuted) {
      this._vibrate(levelConfig.vibrationDuration)
    }

    // 2. UI事件
    this._emitEvent(severity, posture, postureName, duration, detail)

    // 3. Toast提醒（仅严重级别）
    if (severity === 3) {
      this._showToast(`${levelConfig.icon} 检测到${postureName}异常，请注意调整姿势`)
    }

    // 4. 更新触发记录
    this._recordTrigger(severity)

    return true
  }

  /**
   * 震动提醒
   * @private
   * @param {number} duration - 震动时长（毫秒）
   */
  _vibrate(duration) {
    try {
      vibrator.vibrate({
        mode: 'short',
        duration: duration,
      })
    } catch (e) {
      console.error('[AlertTrigger] Vibrate error:', e)
    }
  }

  /**
   * 发送事件给UI层
   * @private
   * @param {number} severity - 严重程度
   * @param {string} posture - 体态类型
   * @param {string} postureName - 体态中文名
   * @param {number} duration - 持续时间（秒）
   * @param {string} detail - 详细描述
   */
  _emitEvent(severity, posture, postureName, duration, detail) {
    if (!this.onEvent) return

    const event = {
      type: 'posture_alert',
      severity,
      posture,
      postureName,
      duration: Math.round(duration),
      detail,
      timestamp: Date.now(),
      levelName: ALERT_LEVELS[severity].name,
      icon: ALERT_LEVELS[severity].icon,
    }

    // 根据级别发送不同事件
    switch (severity) {
      case 1:
        // 轻微：发送震动事件
        this.onEvent('light_alert', event)
        break
      case 2:
        // 中度：发送呼吸灯事件
        this.onEvent('breathing_light', event)
        break
      case 3:
        // 严重：发送弹窗事件
        this.onEvent('popup_alert', event)
        break
    }
  }

  /**
   * 显示Toast
   * @private
   * @param {string} message - 消息内容
   */
  _showToast(message) {
    try {
      prompt.showToast({
        message,
        duration: 3,
      })
    } catch (e) {
      console.error('[AlertTrigger] Toast error:', e)
    }
  }

  /**
   * 检查是否在冷却期
   * @private
   * @param {number} severity - 严重程度
   * @returns {boolean}
   */
  _isInCooldown(severity) {
    const levelConfig = ALERT_LEVELS[severity]
    const lastTime = this.lastTriggerTime[severity]
    const now = Date.now()

    return (now - lastTime) < levelConfig.cooldownMs
  }

  /**
   * 检查是否超过每周期最大次数
   * @private
   * @param {number} severity - 严重程度
   * @returns {boolean}
   */
  _isOverLimit(severity) {
    const levelConfig = ALERT_LEVELS[severity]
    const now = Date.now()
    const countTime = this.countResetTime[severity]

    // 检查是否需要重置计数
    if (now - countTime > levelConfig.cooldownMs) {
      this.triggerCount[severity] = 0
      this.countResetTime[severity] = now
      return false
    }

    return this.triggerCount[severity] >= levelConfig.maxPerPeriod
  }

  /**
   * 记录触发
   * @private
   * @param {number} severity - 严重程度
   */
  _recordTrigger(severity) {
    this.lastTriggerTime[severity] = Date.now()
    this.triggerCount[severity]++
  }

  /**
   * 设置静音模式
   * @param {boolean} muted - 是否静音
   */
  setMuted(muted) {
    this.isMuted = muted
    console.log(`[AlertTrigger] Mute mode: ${muted ? 'on' : 'off'}`)
  }

  /**
   * 获取提醒状态
   * @returns {Object}
   */
  getStatus() {
    const now = Date.now()
    const status = {}

    for (let level = 1; level <= 3; level++) {
      const levelConfig = ALERT_LEVELS[level]
      const lastTime = this.lastTriggerTime[level]
      const cooldownRemaining = Math.max(0, levelConfig.cooldownMs - (now - lastTime))

      status[level] = {
        name: levelConfig.name,
        cooldownRemaining: Math.round(cooldownRemaining / 1000), // 秒
        triggerCount: this.triggerCount[level],
        maxPerPeriod: levelConfig.maxPerPeriod,
      }
    }

    return status
  }

  /**
   * 重置所有触发记录
   */
  reset() {
    this.lastTriggerTime = { 1: 0, 2: 0, 3: 0 }
    this.triggerCount = { 1: 0, 2: 0, 3: 0 }
    this.countResetTime = { 1: 0, 2: 0, 3: 0 }
    console.log('[AlertTrigger] Reset')
  }
}

export { AlertTrigger, ALERT_LEVELS }
export default AlertTrigger

/**
 * posture-engine.js - 体态识别主引擎
 *
 * 整合所有核心模块，提供统一的start()/stop()接口。
 * 内部维护滑动窗口缓冲区，支持50%重叠步进。
 * 订阅sensor-interface的数据流，驱动整个推理pipeline。
 *
 * @module core/posture-engine
 */

import { FeatureExtractor } from './feature-extractor'
import { PostureClassifier } from './posture-classifier'
import { ConfidenceFilter } from './confidence-filter'
import { AdaptiveThreshold } from './adaptive-threshold'
import { AlertTrigger } from './alert-trigger'
import { POSTURE_TYPE } from '../common/constants/postures'

/**
 * 引擎状态枚举
 * @readonly
 */
const ENGINE_STATE = {
  IDLE: 'idle',
  RUNNING: 'running',
  PAUSED: 'paused',
}

class PostureEngine {
  /**
   * @param {Object} options - 配置选项
   * @param {Object} [options.sensorInterface] - 传感器接口实例
   * @param {number} [options.windowSize=250] - 滑动窗口大小
   * @param {number} [options.sampleRate=50] - 采样率
   */
  constructor(options = {}) {
    /** @type {Object} 传感器接口 */
    this.sensorInterface = options.sensorInterface || null

    /** @type {string} 引擎状态 */
    this.state = ENGINE_STATE.IDLE

    /** @type {FeatureExtractor} 特征提取器 */
    this.featureExtractor = new FeatureExtractor({
      windowSize: options.windowSize || 250,
      sampleRate: options.sampleRate || 50,
    })

    /** @type {PostureClassifier} 分类器 */
    this.classifier = null

    /** @type {ConfidenceFilter} 置信度过滤器 */
    this.confidenceFilter = new ConfidenceFilter()

    /** @type {AdaptiveThreshold} 自适应阈值 */
    this.adaptiveThreshold = new AdaptiveThreshold()

    /** @type {AlertTrigger} 提醒触发器 */
    this.alertTrigger = new AlertTrigger()

    /** @type {Object|null} 最新分类结果 */
    this.latestResult = null

    /** @type {Object|null} 最新过滤结果 */
    this.latestFilterResult = null

    /** @type {Function|null} 结果回调 */
    this.onResult = null

    /** @type {Function|null} 事件回调 */
    this.onEvent = null

    /** @type {number} 帧计数器 */
    this.frameCount = 0

    /** @type {number} 推理开始时间 */
    this.inferenceStartTime = 0

    /** @type {Array} 推理延迟记录（用于性能统计） */
    this.latencyRecords = []

    /** @type {Object} 统计信息 */
    this.stats = {
      totalFrames: 0,
      detections: {
        normal: 0,
        sedentary: 0,
        forward_tilt: 0,
        cross_leg: 0,
        walking: 0,
      },
      alerts: {
        level1: 0,
        level2: 0,
        level3: 0,
      },
    }
  }

  /**
   * 初始化引擎
   * @returns {Promise<void>}
   */
  async init() {
    // 初始化自适应阈值
    await this.adaptiveThreshold.init()

    // 使用当前阈值初始化分类器
    const thresholds = this.adaptiveThreshold.getCurrentThresholds()
    this.classifier = new PostureClassifier(thresholds)

    // 设置提醒事件回调
    this.alertTrigger.onEvent = (eventType, event) => {
      this._handleAlertEvent(eventType, event)
    }

    console.log('[PostureEngine] Initialized')
  }

  /**
   * 启动引擎
   * @param {Object} [options] - 启动选项
   * @param {boolean} [options.mockMode=false] - 是否使用Mock模式
   * @param {Object} [options.mockSource] - Mock数据源
   * @returns {boolean} 是否成功启动
   */
  start(options = {}) {
    if (this.state === ENGINE_STATE.RUNNING) {
      console.warn('[PostureEngine] Already running')
      return false
    }

    // 重置状态
    this.featureExtractor.reset()
    this.confidenceFilter.reset()
    this.frameCount = 0
    this.latencyRecords = []

    // 订阅传感器数据
    if (this.sensorInterface) {
      this.sensorInterface.onData((data) => {
        this._processFrame(data)
      })
    }

    this.state = ENGINE_STATE.RUNNING
    console.log('[PostureEngine] Started')
    return true
  }

  /**
   * 停止引擎
   * @returns {boolean} 是否成功停止
   */
  stop() {
    if (this.state === ENGINE_STATE.IDLE) {
      return true
    }

    // 取消传感器订阅
    if (this.sensorInterface) {
      this.sensorInterface.onData(null)
    }

    // 保存历史数据
    this.adaptiveThreshold.saveHistory()

    this.state = ENGINE_STATE.IDLE
    console.log('[PostureEngine] Stopped')
    return true
  }

  /**
   * 暂停引擎
   */
  pause() {
    if (this.state === ENGINE_STATE.RUNNING) {
      this.state = ENGINE_STATE.PAUSED
      console.log('[PostureEngine] Paused')
    }
  }

  /**
   * 恢复引擎
   */
  resume() {
    if (this.state === ENGINE_STATE.PAUSED) {
      this.state = ENGINE_STATE.RUNNING
      console.log('[PostureEngine] Resumed')
    }
  }

  /**
   * 处理一帧传感器数据
   * @private
   * @param {Object} data - 传感器数据 { timestamp, acc, gyro, hr }
   */
  _processFrame(data) {
    if (this.state !== ENGINE_STATE.RUNNING) return

    // 记录推理开始时间
    this.inferenceStartTime = Date.now()

    // 1. 特征提取
    const features = this.featureExtractor.input(data)
    if (!features) {
      // 窗口未满，跳过分类
      return
    }

    // 2. 分类
    const classification = this.classifier.classify(features)

    // 3. 置信度过滤
    const filterResult = this.confidenceFilter.filter(classification)

    // 4. 记录统计
    this._updateStats(filterResult)

    // 5. 触发提醒
    if (filterResult.confirmed) {
      this.alertTrigger.trigger(filterResult)
    }

    // 6. 更新自适应阈值
    if (filterResult.confirmed && filterResult.duration > 0) {
      this.adaptiveThreshold.recordDetection(
        filterResult.posture,
        features,
        filterResult.duration
      )
    }

    // 7. 记录结果
    this.latestResult = classification
    this.latestFilterResult = filterResult

    // 8. 计算推理延迟
    const latency = Date.now() - this.inferenceStartTime
    this.latencyRecords.push(latency)
    if (this.latencyRecords.length > 100) {
      this.latencyRecords.shift()
    }

    // 9. 触发结果回调
    if (this.onResult) {
      this.onResult(filterResult, features)
    }

    this.frameCount++
  }

  /**
   * 处理提醒事件
   * @private
   * @param {string} eventType - 事件类型
   * @param {Object} event - 事件数据
   */
  _handleAlertEvent(eventType, event) {
    // 更新统计
    if (event.severity === 1) this.stats.alerts.level1++
    else if (event.severity === 2) this.stats.alerts.level2++
    else if (event.severity === 3) this.stats.alerts.level3++

    // 触发事件回调
    if (this.onEvent) {
      this.onEvent(eventType, event)
    }
  }

  /**
   * 更新统计信息
   * @private
   * @param {Object} filterResult - 过滤结果
   */
  _updateStats(filterResult) {
    this.stats.totalFrames++

    const posture = filterResult.posture
    if (this.stats.detections[posture] !== undefined) {
      this.stats.detections[posture]++
    }
  }

  /**
   * 获取最新结果
   * @returns {{classification: Object, filter: Object}}
   */
  getLatestResult() {
    return {
      classification: this.latestResult,
      filter: this.latestFilterResult,
    }
  }

  /**
   * 获取统计信息
   * @returns {Object}
   */
  getStats() {
    const avgLatency = this.latencyRecords.length > 0
      ? this.latencyRecords.reduce((a, b) => a + b, 0) / this.latencyRecords.length
      : 0

    const maxLatency = this.latencyRecords.length > 0
      ? Math.max(...this.latencyRecords)
      : 0

    return {
      ...this.stats,
      frameCount: this.frameCount,
      avgLatency: Math.round(avgLatency * 100) / 100,
      maxLatency,
      alertStatus: this.alertTrigger.getStatus(),
    }
  }

  /**
   * 获取当前体态状态（简化接口，用于UI）
   * @returns {Object}
   */
  getCurrentPosture() {
    if (!this.latestFilterResult) {
      return {
        type: POSTURE_TYPE.NORMAL,
        name: '等待数据...',
        icon: '⏳',
        confidence: 0,
        severity: 1,
        confirmed: false,
        detail: '',
      }
    }

    const result = this.latestFilterResult
    const names = {
      normal: '正常',
      sedentary: '久坐',
      forward_tilt: '低头前倾',
      cross_leg: '跷二郎腿',
      walking: '行走中',
    }

    const icons = {
      normal: '😊',
      sedentary: '🪑',
      forward_tilt: '📱',
      cross_leg: '🦵',
      walking: '🚶',
    }

    return {
      type: result.posture,
      name: names[result.posture] || '未知',
      icon: icons[result.posture] || '❓',
      confidence: result.confidence,
      severity: result.severity,
      confirmed: result.confirmed,
      detail: result.detail,
      duration: result.duration,
    }
  }

  /**
   * 更新阈值
   * @param {Object} thresholds - 新阈值
   */
  updateThresholds(thresholds) {
    this.adaptiveThreshold.currentThresholds = thresholds
    this.classifier.updateThresholds(thresholds)
    console.log('[PostureEngine] Thresholds updated')
  }

  /**
   * 设置提醒静音
   * @param {boolean} muted - 是否静音
   */
  setAlertMuted(muted) {
    this.alertTrigger.setMuted(muted)
  }

  /**
   * 检查日期更新
   */
  checkDateUpdate() {
    this.adaptiveThreshold.checkDateUpdate()
  }
}

export { PostureEngine, ENGINE_STATE }
export default PostureEngine

/**
 * 差分隐私噪声注入模块
 *
 * 实现 Laplace 机制，为数值型敏感数据添加随机噪声，
 * 保证在 ε-差分隐私保护下的数据可用性。
 *
 * 数学原理：
 * - Laplace 分布：Lap(b) 的 PDF 为 f(x) = (1/2b) * exp(-|x|/b)
 * - 其中 b = sensitivity / epsilon
 * - 对于任意相邻数据集 D, D'，输出 M(D) 和 M(D') 的比值 ≤ e^ε
 *
 * @module privacy/differential-privacy
 */

/**
 * Laplace 机制差分隐私实现
 */
export class DifferentialPrivacy {
  /**
   * 为数值添加 Laplace 噪声
   *
   * @param {number} value - 原始数值
   * @param {number} sensitivity - 全局敏感度 Δf（查询函数的最大变化量）
   * @param {number} epsilon - 隐私预算 ε，越小隐私保护越强
   * @returns {number} 添加噪声后的值
   */
  static addNoise(value, sensitivity, epsilon) {
    if (typeof value !== 'number' || isNaN(value)) {
      return value
    }
    if (sensitivity <= 0 || epsilon <= 0) {
      throw new Error('sensitivity and epsilon must be positive')
    }

    const scale = sensitivity / epsilon
    const noise = DifferentialPrivacy._laplaceSample(scale)
    return value + noise
  }

  /**
   * 批量为多个值添加噪声（使用相同的隐私预算分配）
   *
   * @param {number[]} values - 原始数值数组
   * @param {number} sensitivity - 全局敏感度
   * @param {number} epsilon - 总隐私预算
   * @returns {number[]} 添加噪声后的值数组
   */
  static addNoiseBatch(values, sensitivity, epsilon) {
    if (!Array.isArray(values)) return values
    // 隐私预算均分（序列组合性）
    const perQueryEpsilon = epsilon / values.length
    return values.map(v => DifferentialPrivacy.addNoise(v, sensitivity, perQueryEpsilon))
  }

  /**
   * 校准 epsilon 以满足 (ε, δ)-近似差分隐私
   *
   * @param {number} delta - 近似参数 δ（通常取 1e-5 或更小）
   * @param {number} sensitivity - 全局敏感度
   * @param {number} targetVariance - 目标方差
   * @returns {number} 推荐的 epsilon 值
   */
  static calibrateNoise(delta, sensitivity, targetVariance) {
    // 对于 Laplace 机制：Var = 2 * (sensitivity/epsilon)^2
    // 解 epsilon = sensitivity * sqrt(2 / targetVariance)
    if (targetVariance <= 0) {
      throw new Error('targetVariance must be positive')
    }
    return sensitivity * Math.sqrt(2 / targetVariance)
  }

  /**
   * 生成符合 Laplace 分布的随机样本
   * 使用逆变换采样法：X = -b * sgn(U) * ln(1 - 2|U|)
   * 其中 U ~ Uniform(-0.5, 0.5)
   *
   * @param {number} scale - 尺度参数 b = sensitivity / epsilon
   * @returns {number} Laplace 分布随机样本
   * @private
   */
  static _laplaceSample(scale) {
    // 生成 (-0.5, 0.5) 范围内的均匀分布随机数
    const u = Math.random() - 0.5
    // 逆变换采样
    return -scale * Math.sign(u) * Math.log(1 - 2 * Math.abs(u))
  }

  /**
   * 评估隐私损失（用于隐私预算追踪）
   *
   * @param {number} epsilon - 已使用的隐私预算
   * @param {number} numQueries - 查询次数
   * @returns {number} 累积隐私损失
   */
  static cumulativePrivacyLoss(epsilon, numQueries) {
    // 基本组合定理：k 次 ε-DP 查询的总隐私损失为 k*ε
    return epsilon * numQueries
  }

  /**
   * 高级组合定理（更紧的界）
   *
   * @param {number} epsilon - 单次隐私预算
   * @param {number} numQueries - 查询次数
   * @param {number} delta - 近似参数
   * @returns {number} 更紧的隐私损失界
   */
  static advancedComposition(epsilon, numQueries, delta = 1e-5) {
    const k = numQueries
    const ep2 = epsilon * epsilon
    // 定理：k 次 (ε,δ)-DP 的组合为 (ε', kδ + δ')
    // ε' = ε * sqrt(2k * ln(1/δ')) + k * ε * (e^ε - 1)
    const deltaPrime = delta / 2
    const term1 = epsilon * Math.sqrt(2 * k * Math.log(1 / deltaPrime))
    const term2 = k * epsilon * (Math.exp(epsilon) - 1)
    return term1 + term2
  }
}

export default DifferentialPrivacy

/**
 * 脱敏规则引擎
 *
 * 对原始传感器数据和 AI 引擎输出进行隐私脱敏处理，
 * 包括时间戳模糊化、生理数据区间化、坐标差分隐私噪声注入等。
 *
 * 核心原则：
 * 1. 原始传感器数据脱敏后立即释放，不得保留明文副本
 * 2. 所有输出均标记 desensitized: true
 * 3. 同一输入多次脱敏结果不同（差分隐私噪声随机性）
 *
 * @module privacy/desensitizer
 */

import { DifferentialPrivacy } from './differential-privacy'

/**
 * 脱敏规则配置
 */
const DESENSITIZE_RULES = {
  // 时间戳：精确毫秒 → 模糊到 5 分钟区间
  TIMESTAMP: {
    type: 'range',
    intervalMs: 5 * 60 * 1000, // 5 分钟
  },
  // 心率：精确值 → 区间化
  HEART_RATE: {
    type: 'bucket',
    bucketSize: 5, // 5 bpm 区间
  },
  // 运动坐标：差分隐私噪声
  MOTION_COORD: {
    type: 'dp_noise',
    epsilon: 0.1,
    sensitivity: 1.0,
  },
  // 步数：模糊到 10 步区间
  STEP_COUNT: {
    type: 'bucket',
    bucketSize: 10,
  },
  // 原始波形：丢弃，仅保留统计特征
  RAW_WAVEFORM: {
    type: 'discard',
  },
}

/**
 * 脱敏规则引擎
 */
export class Desensitizer {
  constructor() {
    this._rules = { ...DESENSITIZE_RULES }
    this._dp = DifferentialPrivacy
  }

  /**
   * 脱敏传感器原始数据
   *
   * 输入格式：
   * {
   *   timestamp: 1700000000000,
   *   acc: { x: 0.1, y: -9.8, z: 0.2 },
   *   gyro: { pitch: 5.0, roll: -2.0 },
   *   heartRate: 72,
   *   steps: 1234
   * }
   *
   * @param {Object} rawData - 原始传感器数据
   * @returns {Object} 脱敏后的特征包
   */
  desensitizeSensorData(rawData) {
    if (!rawData) return null

    const result = {
      desensitized: true,
      desensitizedAt: Date.now(),
    }

    // 时间戳模糊化
    if (rawData.timestamp !== undefined) {
      result.timestampRange = this._desensitizeTimestamp(rawData.timestamp)
    }

    // 加速度数据：差分隐私噪声
    if (rawData.acc) {
      result.acc = {
        x: this._addDpNoise(rawData.acc.x, this._rules.MOTION_COORD),
        y: this._addDpNoise(rawData.acc.y, this._rules.MOTION_COORD),
        z: this._addDpNoise(rawData.acc.z, this._rules.MOTION_COORD),
      }
    }

    // 陀螺仪数据：差分隐私噪声
    if (rawData.gyro) {
      result.gyro = {
        pitch: this._addDpNoise(rawData.gyro.pitch, this._rules.MOTION_COORD),
        roll: this._addDpNoise(rawData.gyro.roll, this._rules.MOTION_COORD),
      }
    }

    // 心率：区间化
    if (rawData.heartRate !== undefined) {
      result.heartRateRange = this._desensitizeHeartRate(rawData.heartRate)
    }

    // 步数：模糊化
    if (rawData.steps !== undefined) {
      result.stepRange = this._desensitizeStepCount(rawData.steps)
    }

    // 原始波形：丢弃（标记为已丢弃）
    result.rawWaveformDiscarded = true

    return result
  }

  /**
   * 脱敏 AI 引擎输出
   *
   * 输入格式（PostureEngine 输出）：
   * {
   *   posture: 'normal',
   *   confidence: 0.92,
   *   severity: 1,
   *   duration: 45,
   *   timestamp: 1700000000000,
   *   features: { accMean, accVar, gyroPitch, ... }
   * }
   *
   * @param {Object} engineOutput - AI 引擎输出
   * @returns {Object} 脱敏后的输出
   */
  desensitizeEngineOutput(engineOutput) {
    if (!engineOutput) return null

    const result = {
      desensitized: true,
      desensitizedAt: Date.now(),
    }

    // 姿态类型：直接保留（非敏感）
    result.posture = engineOutput.posture

    // 置信度：保留（用于统计，不敏感）
    result.confidence = engineOutput.confidence

    // 严重程度：保留
    result.severity = engineOutput.severity

    // 持续时间：区间化（5分钟）
    if (engineOutput.duration !== undefined) {
      result.durationRange = this._desensitizeDuration(engineOutput.duration)
    }

    // 时间戳：模糊化
    if (engineOutput.timestamp !== undefined) {
      result.timestampRange = this._desensitizeTimestamp(engineOutput.timestamp)
    }

    // 特征向量：部分脱敏
    if (engineOutput.features) {
      result.features = this._desensitizeFeatures(engineOutput.features)
    }

    return result
  }

  /**
   * 脱敏时间戳到 5 分钟区间
   *
   * @param {number} timestamp - 精确时间戳（毫秒）
   * @returns {Object} { start, end, label }
   * @private
   */
  _desensitizeTimestamp(timestamp) {
    const interval = this._rules.TIMESTAMP.intervalMs
    const bucketStart = Math.floor(timestamp / interval) * interval
    const bucketEnd = bucketStart + interval

    const start = new Date(bucketStart)
    const end = new Date(bucketEnd)
    const label = `${this._pad(start.getHours())}:${this._pad(start.getMinutes())}-${this._pad(end.getHours())}:${this._pad(end.getMinutes())}`

    return {
      start: bucketStart,
      end: bucketEnd,
      label,
    }
  }

  /**
   * 心率区间化
   *
   * @param {number} bpm - 精确心率
   * @returns {Object} { min, max, label }
   * @private
   */
  _desensitizeHeartRate(bpm) {
    const bucketSize = this._rules.HEART_RATE.bucketSize
    const min = Math.floor(bpm / bucketSize) * bucketSize
    const max = min + bucketSize

    return {
      min,
      max,
      label: `${min}-${max}`,
    }
  }

  /**
   * 步数模糊化
   *
   * @param {number} steps - 精确步数
   * @returns {Object} { min, max, label }
   * @private
   */
  _desensitizeStepCount(steps) {
    const bucketSize = this._rules.STEP_COUNT.bucketSize
    const min = Math.floor(steps / bucketSize) * bucketSize
    const max = min + bucketSize

    return {
      min,
      max,
      label: `${min}-${max}`,
    }
  }

  /**
   * 持续时间区间化（5分钟）
   *
   * @param {number} seconds - 精确秒数
   * @returns {Object} { minSec, maxSec, label }
   * @private
   */
  _desensitizeDuration(seconds) {
    const intervalSec = 300 // 5 分钟
    const min = Math.floor(seconds / intervalSec) * intervalSec
    const max = min + intervalSec

    const minMin = Math.floor(min / 60)
    const maxMin = Math.floor(max / 60)

    return {
      minSec: min,
      maxSec: max,
      label: `${minMin}-${maxMin}分钟`,
    }
  }

  /**
   * 特征向量脱敏
   *
   * @param {Object} features - 原始特征
   * @returns {Object} 脱敏后的特征
   * @private
   */
  _desensitizeFeatures(features) {
    const result = {}

    // 加速度均值：添加差分隐私噪声
    if (features.accMean) {
      result.accMean = {
        x: this._addDpNoise(features.accMean.x, this._rules.MOTION_COORD),
        y: this._addDpNoise(features.accMean.y, this._rules.MOTION_COORD),
        z: this._addDpNoise(features.accMean.z, this._rules.MOTION_COORD),
      }
    }

    // 加速度方差：保留（统计特征，不敏感）
    if (features.accVar) {
      result.accVar = features.accVar
    }

    // 陀螺仪角度：添加差分隐私噪声
    if (features.gyroPitch !== undefined) {
      result.gyroPitch = this._addDpNoise(features.gyroPitch, this._rules.MOTION_COORD)
    }
    if (features.gyroRoll !== undefined) {
      result.gyroRoll = this._addDpNoise(features.gyroRoll, this._rules.MOTION_COORD)
    }

    // 主频、过零率、不对称指数：保留（统计特征）
    if (features.dominantFreq !== undefined) {
      result.dominantFreq = features.dominantFreq
    }
    if (features.zeroCrossRate !== undefined) {
      result.zeroCrossRate = features.zeroCrossRate
    }
    if (features.asymmetryIndex !== undefined) {
      result.asymmetryIndex = features.asymmetryIndex
    }

    // 姿态四元数：添加差分隐私噪声
    if (features.orientation) {
      result.orientation = {
        w: this._addDpNoise(features.orientation.w, this._rules.MOTION_COORD),
        x: this._addDpNoise(features.orientation.x, this._rules.MOTION_COORD),
        y: this._addDpNoise(features.orientation.y, this._rules.MOTION_COORD),
        z: this._addDpNoise(features.orientation.z, this._rules.MOTION_COORD),
      }
    }

    return result
  }

  /**
   * 添加差分隐私噪声
   *
   * @param {number} value - 原始值
   * @param {Object} rule - 噪声规则配置
   * @returns {number} 添加噪声后的值
   * @private
   */
  _addDpNoise(value, rule) {
    if (typeof value !== 'number' || isNaN(value)) return value
    return this._dp.addNoise(value, rule.sensitivity, rule.epsilon)
  }

  /**
   * 数字补零
   *
   * @param {number} num - 数字
   * @returns {string} 补零后的字符串
   * @private
   */
  _pad(num) {
    return String(num).padStart(2, '0')
  }

  /**
   * 更新脱敏规则
   *
   * @param {string} ruleName - 规则名称
   * @param {Object} config - 新规则配置
   */
  updateRule(ruleName, config) {
    if (this._rules[ruleName]) {
      this._rules[ruleName] = { ...this._rules[ruleName], ...config }
    }
  }

  /**
   * 获取当前规则配置（只读）
   *
   * @returns {Object} 规则配置副本
   */
  getRules() {
    return JSON.parse(JSON.stringify(this._rules))
  }
}

export default Desensitizer

/**
 * 密钥派生与分片模块
 *
 * 实现分层密钥管理体系：
 * - 主密钥：PBKDF2-HMAC-SHA256 派生
 * - L1 密钥：HKDF 派生，普通安全区域
 * - L2 密钥：单独派生，隔离上下文（模拟安全域）
 * - L3 密钥：Shamir's Secret Sharing (2-of-3) 分片
 *
 * 安全原则：
 * 1. 密钥不得硬编码，必须在运行时派生
 * 2. 主密钥基于 deviceId + userPin + salt
 * 3. L3 密钥使用 Shamir 分片，2/3 恢复
 *
 * @module privacy/key-derivation
 */

/**
 * 密钥派生与分片管理器
 */
export class KeyDerivation {
  constructor() {
    // 主密钥缓存（运行时）
    this._masterKey = null
    // L3 密钥分片缓存
    this._l3Shards = {
      shard1: null, // 内存中临时持有
      shard2: null, // 加密写入文件头
      shard3: null, // 独立小文件
    }
    // 设备标识（运行时获取）
    this._deviceId = null
    // 用户 PIN
    this._userPin = null
    // 盐值
    this._salt = null
  }

  /**
   * 初始化密钥系统
   *
   * @param {Object} params
   * @param {string} params.deviceId - 设备唯一标识
   * @param {string} params.userPin - 用户 PIN 码
   * @param {string} [params.salt] - 盐值（可选，自动生成）
   * @returns {Promise<boolean>} 初始化是否成功
   */
  async init({ deviceId, userPin, salt }) {
    if (!deviceId || !userPin) {
      throw new Error('deviceId and userPin are required')
    }

    this._deviceId = deviceId
    this._userPin = userPin
    this._salt = salt || this._generateSalt()

    // 派生主密钥
    this._masterKey = await this._deriveMasterKey()

    // 派生各级密钥
    await this._deriveLevelKeys()

    // 生成 L3 Shamir 分片
    await this._generateL3Shards()

    return true
  }

  /**
   * 获取指定级别的加密密钥
   *
   * @param {number} level - 数据级别 (1, 2, 3)
   * @returns {Promise<CryptoKey>} 对应级别的密钥
   */
  async getKey(level) {
    if (!this._masterKey) {
      throw new Error('KeyDerivation not initialized')
    }

    switch (level) {
      case 1:
        return this._deriveAESKey('l1', 128)
      case 2:
        return this._deriveAESKey('l2', 256)
      case 3:
        return this._reconstructL3Key()
      default:
        throw new Error(`Invalid key level: ${level}`)
    }
  }

  /**
   * 获取 L3 密钥分片
   *
   * @returns {Object} { shard1, shard2, shard3 }
   */
  getL3Shards() {
    return {
      shard1: this._l3Shards.shard1 ? { ...this._l3Shards.shard1 } : null,
      shard2: this._l3Shards.shard2 ? { ...this._l3Shards.shard2 } : null,
      shard3: this._l3Shards.shard3 ? { ...this._l3Shards.shard3 } : null,
    }
  }

  /**
   * 从分片恢复密钥（需要至少 2 个分片）
   *
   * @param {Array} shards - 分片数组，每个分片 { index, value }
   * @returns {Promise<CryptoKey>} 恢复的密钥
   */
  async reconstructKey(shards) {
    if (!shards || shards.length < 2) {
      throw new Error('At least 2 shards required for key reconstruction')
    }

    // 使用拉格朗日插值恢复主密钥
    const recovered = this._lagrangeInterpolate(shards)

    // 用恢复的值派生 AES 密钥
    return this._importKey(recovered, 256)
  }

  /**
   * PBKDF2-HMAC-SHA256 派生主密钥
   *
   * @returns {Promise<ArrayBuffer>} 主密钥
   * @private
   */
  async _deriveMasterKey() {
    const iterations = 10000
    const keyLength = 32 // 256 bits

    // 组合输入材料
    const material = this._deviceId + ':' + this._userPin

    // 导入密码材料
    const passwordKey = await crypto.subtle.importKey(
      'raw',
      this._encoder().encode(material),
      'PBKDF2',
      false,
      ['deriveBits']
    )

    // PBKDF2 派生
    const derivedBits = await crypto.subtle.deriveBits(
      {
        name: 'PBKDF2',
        salt: this._encoder().encode(this._salt),
        iterations: iterations,
        hash: 'SHA-256',
      },
      passwordKey,
      keyLength * 8
    )

    return derivedBits
  }

  /**
   * 派生各级密钥
   *
   * @private
   */
  async _deriveLevelKeys() {
    // L1 密钥：HKDF 派生（使用 Web Crypto HKDF 或简化版）
    this._l1Key = await this._hkdfDerive('posture-guard-l1', 16)

    // L2 密钥：单独派生（模拟隔离上下文）
    this._l2Key = await this._hkdfDerive('posture-guard-l2', 32)
  }

  /**
   * HKDF 简化实现
   *
   * @param {string} info - 上下文信息
   * @param {number} length - 密钥长度（字节）
   * @returns {Promise<ArrayBuffer>} 派生密钥
   * @private
   */
  async _hkdfDerive(info, length) {
    // 使用 HMAC-SHA256 进行简化 HKDF
    const hmacKey = await crypto.subtle.importKey(
      'raw',
      this._masterKey,
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    )

    // Extract 阶段：PRK = HMAC-Hash(salt, IKM)
    const prk = await crypto.subtle.sign('HMAC', hmacKey, this._encoder().encode('hkdf-extract'))

    // Expand 阶段：T(1) = HMAC-Hash(PRK, info || 0x01)
    const prkKey = await crypto.subtle.importKey(
      'raw',
      prk,
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    )

    const infoBytes = this._encoder().encode(info)
    const concat = new Uint8Array(infoBytes.length + 1)
    concat.set(infoBytes)
    concat[infoBytes.length] = 0x01

    const okm = await crypto.subtle.sign('HMAC', prkKey, concat)

    // 截取所需长度
    return okm.slice(0, length)
  }

  /**
   * 派生 AES 密钥
   *
   * @param {string} purpose - 用途标识
   * @param {number} bits - 密钥位数 (128 or 256)
   * @returns {Promise<CryptoKey>} AES 密钥
   * @private
   */
  async _deriveAESKey(purpose, bits) {
    const keyMaterial = purpose === 'l1' ? this._l1Key : this._l2Key

    return crypto.subtle.importKey(
      'raw',
      keyMaterial,
      { name: 'AES-GCM' },
      false,
      ['encrypt', 'decrypt']
    )
  }

  /**
   * 导入原始密钥材料
   *
   * @param {ArrayBuffer} rawKey - 原始密钥字节
   * @param {number} bits - 位数
   * @returns {Promise<CryptoKey>} AES 密钥
   * @private
   */
  async _importKey(rawKey, bits) {
    return crypto.subtle.importKey(
      'raw',
      rawKey,
      { name: 'AES-GCM' },
      false,
      ['encrypt', 'decrypt']
    )
  }

  /**
   * 生成 L3 Shamir 分片
   *
   * Shamir's Secret Sharing (2-of-3)：
   * - 将密钥视为有限域上的多项式系数
   * - 构造 f(x) = secret + a*x (mod p)
   * - 计算 f(1), f(2), f(3) 作为三个分片
   * - 任意两个分片可通过拉格朗日插值恢复 secret
   *
   * @private
   */
  async _generateL3Shards() {
    // 将主密钥转换为大整数（简化版：使用前 16 字节）
    const keyBytes = new Uint8Array(this._masterKey)
    const secret = this._bytesToBigInt(keyBytes.slice(0, 16))

    // 有限域质数（2^127 - 1，梅森素数）
    const prime = BigInt('170141183460469231731687303715884105727')

    // 生成随机系数 a
    const a = this._randomBigInt(prime)

    // 构造多项式 f(x) = secret + a*x mod p
    const f = (x) => (secret + a * x) % prime

    // 计算三个分片
    this._l3Shards.shard1 = {
      index: 1,
      value: this._bigIntToHex(f(BigInt(1))),
    }
    this._l3Shards.shard2 = {
      index: 2,
      value: this._bigIntToHex(f(BigInt(2))),
    }
    this._l3Shards.shard3 = {
      index: 3,
      value: this._bigIntToHex(f(BigInt(3))),
    }
  }

  /**
   * 拉格朗日插值恢复密钥
   *
   * @param {Array} shards - 至少 2 个分片 [{index, value}, ...]
   * @returns {ArrayBuffer} 恢复的密钥
   * @private
   */
  _lagrangeInterpolate(shards) {
    const prime = BigInt('170141183460469231731687303715884105727')

    let result = BigInt(0)

    for (let i = 0; i < shards.length; i++) {
      const xi = BigInt(shards[i].index)
      const yi = BigInt('0x' + shards[i].value)

      let numerator = BigInt(1)
      let denominator = BigInt(1)

      for (let j = 0; j < shards.length; j++) {
        if (i === j) continue
        const xj = BigInt(shards[j].index)
        numerator = (numerator * (BigInt(0) - xj)) % prime
        denominator = (denominator * (xi - xj)) % prime
      }

      // 计算模逆
      const invDenom = this._modInverse(denominator, prime)
      const lagrangeCoeff = (numerator * invDenom) % prime

      result = (result + yi * lagrangeCoeff) % prime
    }

    // 确保结果为正数
    result = (result + prime) % prime

    // 转换回字节数组
    return this._bigIntToBytes(result, 16)
  }

  /**
   * 模逆运算（扩展欧几里得算法）
   *
   * @param {BigInt} a - 输入
   * @param {BigInt} m - 模数
   * @returns {BigInt} a^(-1) mod m
   * @private
   */
  _modInverse(a, m) {
    let [old_r, r] = [a % m, m]
    let [old_s, s] = [BigInt(1), BigInt(0)]

    while (r !== BigInt(0)) {
      const quotient = old_r / r
      ;[old_r, r] = [r, old_r - quotient * r]
      ;[old_s, s] = [s, old_s - quotient * s]
    }

    return (old_s % m + m) % m
  }

  /**
   * 生成盐值
   *
   * @returns {string} 十六进制盐值
   * @private
   */
  _generateSalt() {
    const array = new Uint8Array(16)
    crypto.getRandomValues(array)
    return Array.from(array, b => b.toString(16).padStart(2, '0')).join('')
  }

  /**
   * 字节数组转 BigInt
   *
   * @param {Uint8Array} bytes
   * @returns {BigInt}
   * @private
   */
  _bytesToBigInt(bytes) {
    let result = BigInt(0)
    for (let i = 0; i < bytes.length; i++) {
      result = (result << BigInt(8)) | BigInt(bytes[i])
    }
    return result
  }

  /**
   * BigInt 转十六进制字符串
   *
   * @param {BigInt} value
   * @returns {string}
   * @private
   */
  _bigIntToHex(value) {
    return value.toString(16).padStart(32, '0')
  }

  /**
   * BigInt 转字节数组
   *
   * @param {BigInt} value
   * @param {number} length
   * @returns {ArrayBuffer}
   * @private
   */
  _bigIntToBytes(value, length) {
    const hex = value.toString(16).padStart(length * 2, '0')
    const bytes = new Uint8Array(length)
    for (let i = 0; i < length; i++) {
      bytes[i] = parseInt(hex.substr(i * 2, 2), 16)
    }
    return bytes.buffer
  }

  /**
   * 生成指定范围内的随机 BigInt
   *
   * @param {BigInt} max
   * @returns {BigInt}
   * @private
   */
  _randomBigInt(max) {
    const bytes = new Uint8Array(16)
    crypto.getRandomValues(bytes)
    let value = this._bytesToBigInt(bytes)
    return value % max
  }

  /**
   * 获取 TextEncoder
   *
   * @returns {TextEncoder}
   * @private
   */
  _encoder() {
    return new TextEncoder()
  }
}

export default KeyDerivation

/**
 * 加密/解密管理模块
 *
 * 实现轻量级 AES-GCM 加密系统：
 * - L1：AES-128-GCM（普通统计数据）
 * - L2：AES-256-GCM（生理趋势数据）
 * - L3：AES-256-GCM（原始特征，24h 强制销毁）
 *
 * 加密输出格式：
 * { iv: base64, ciphertext: base64, authTag: base64, level: number }
 *
 * @module privacy/crypto-manager
 */

import { KeyDerivation } from './key-derivation'

/**
 * 加密级别
 */
export const CRYPTO_LEVEL = {
  L1: 1, // AES-128-GCM
  L2: 2, // AES-256-GCM
  L3: 3, // AES-256-GCM（Shamir 分片）
}

/**
 * 加密管理器
 */
export class CryptoManager {
  constructor() {
    this._keyDerivation = new KeyDerivation()
    this._initialized = false
    // 密钥缓存
    this._keyCache = {}
  }

  /**
   * 初始化加密系统
   *
   * @param {Object} params
   * @param {string} params.deviceId - 设备标识
   * @param {string} params.userPin - 用户 PIN
   * @param {string} [params.salt] - 盐值
   * @returns {Promise<boolean>}
   */
  async init(params) {
    await this._keyDerivation.init(params)
    this._initialized = true
    // 预派生 L1 和 L2 密钥
    this._keyCache[CRYPTO_LEVEL.L1] = await this._keyDerivation.getKey(1)
    this._keyCache[CRYPTO_LEVEL.L2] = await this._keyDerivation.getKey(2)
    return true
  }

  /**
   * 加密数据
   *
   * @param {Object|string|ArrayBuffer} data - 待加密数据
   * @param {number} level - 加密级别 (1, 2, 3)
   * @returns {Promise<Object>} 加密后的数据包 { iv, ciphertext, authTag, level }
   */
  async encrypt(data, level = CRYPTO_LEVEL.L1) {
    if (!this._initialized) {
      throw new Error('CryptoManager not initialized')
    }

    const key = await this._getKeyForLevel(level)
    const iv = this._generateIV()
    const encodedData = this._encodeData(data)

    // AES-GCM 加密
    const encrypted = await crypto.subtle.encrypt(
      {
        name: 'AES-GCM',
        iv: iv,
        tagLength: 128, // 128-bit auth tag
      },
      key,
      encodedData
    )

    // 分离密文和认证标签
    const encryptedArray = new Uint8Array(encrypted)
    const ciphertext = encryptedArray.slice(0, encryptedArray.length - 16)
    const authTag = encryptedArray.slice(encryptedArray.length - 16)

    return {
      iv: this._arrayBufferToBase64(iv),
      ciphertext: this._arrayBufferToBase64(ciphertext.buffer),
      authTag: this._arrayBufferToBase64(authTag.buffer),
      level,
      algorithm: level === CRYPTO_LEVEL.L1 ? 'AES-128-GCM' : 'AES-256-GCM',
    }
  }

  /**
   * 解密数据
   *
   * @param {Object} encryptedBlob - 加密数据包 { iv, ciphertext, authTag, level }
   * @returns {Promise<Object|string|ArrayBuffer>} 解密后的数据
   */
  async decrypt(encryptedBlob) {
    if (!this._initialized) {
      throw new Error('CryptoManager not initialized')
    }

    const { iv, ciphertext, authTag, level } = encryptedBlob
    const key = await this._getKeyForLevel(level)

    // 合并密文和认证标签
    const ciphertextBytes = this._base64ToArrayBuffer(ciphertext)
    const authTagBytes = this._base64ToArrayBuffer(authTag)
    const combined = new Uint8Array(ciphertextBytes.byteLength + authTagBytes.byteLength)
    combined.set(new Uint8Array(ciphertextBytes))
    combined.set(new Uint8Array(authTagBytes), ciphertextBytes.byteLength)

    // AES-GCM 解密
    const decrypted = await crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv: this._base64ToArrayBuffer(iv),
        tagLength: 128,
      },
      key,
      combined.buffer
    )

    return this._decodeData(decrypted)
  }

  /**
   * 生成随机 IV（96 bits for AES-GCM）
   *
   * @returns {Uint8Array} 12 字节 IV
   * @private
   */
  _generateIV() {
    const iv = new Uint8Array(12) // 96 bits
    crypto.getRandomValues(iv)
    return iv
  }

  /**
   * 根据级别获取密钥
   *
   * @param {number} level
   * @returns {Promise<CryptoKey>}
   * @private
   */
  async _getKeyForLevel(level) {
    // L3 需要实时从分片重建
    if (level === CRYPTO_LEVEL.L3) {
      if (!this._keyCache[CRYPTO_LEVEL.L3]) {
        this._keyCache[CRYPTO_LEVEL.L3] = await this._keyDerivation.getKey(3)
      }
      return this._keyCache[CRYPTO_LEVEL.L3]
    }

    return this._keyCache[level]
  }

  /**
   * 编码数据为 ArrayBuffer
   *
   * @param {Object|string} data
   * @returns {ArrayBuffer}
   * @private
   */
  _encodeData(data) {
    if (data instanceof ArrayBuffer) {
      return data
    }

    const encoder = new TextEncoder()

    if (typeof data === 'string') {
      return encoder.encode(data).buffer
    }

    // 对象序列化为 JSON
    return encoder.encode(JSON.stringify(data)).buffer
  }

  /**
   * 解码 ArrayBuffer 为原始数据
   *
   * @param {ArrayBuffer} buffer
   * @returns {Object|string}
   * @private
   */
  _decodeData(buffer) {
    const decoder = new TextDecoder()
    const text = decoder.decode(buffer)

    // 尝试解析为 JSON
    try {
      return JSON.parse(text)
    } catch {
      return text
    }
  }

  /**
   * ArrayBuffer 转 Base64
   *
   * @param {ArrayBuffer} buffer
   * @returns {string}
   * @private
   */
  _arrayBufferToBase64(buffer) {
    const bytes = new Uint8Array(buffer)
    let binary = ''
    for (let i = 0; i < bytes.length; i++) {
      binary += String.fromCharCode(bytes[i])
    }
    return btoa(binary)
  }

  /**
   * Base64 转 ArrayBuffer
   *
   * @param {string} base64
   * @returns {ArrayBuffer}
   * @private
   */
  _base64ToArrayBuffer(base64) {
    const binary = atob(base64)
    const bytes = new Uint8Array(binary.length)
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i)
    }
    return bytes.buffer
  }

  /**
   * 清除密钥缓存（安全擦除）
   */
  secureWipe() {
    // 清除密钥缓存引用
    this._keyCache = {}
    this._initialized = false
  }

  /**
   * 获取 L3 密钥分片（用于外部存储）
   *
   * @returns {Object} { shard1, shard2, shard3 }
   */
  getL3Shards() {
    return this._keyDerivation.getL3Shards()
  }

  /**
   * 从分片恢复 L3 密钥（用于解密）
   *
   * @param {Array} shards - 至少 2 个分片
   * @returns {Promise<CryptoKey>}
   */
  async reconstructL3Key(shards) {
    const key = await this._keyDerivation.reconstructKey(shards)
    this._keyCache[CRYPTO_LEVEL.L3] = key
    return key
  }
}

export default CryptoManager

/**
 * 安全存储封装模块
 *
 * 封装所有文件 IO 操作，上层模块禁止直接调用系统文件 API。
 * 所有数据写入前必须经过脱敏检查和加密处理。
 *
 * 写入流程：数据 → 脱敏检查 → 加密 → 写入磁盘
 * 读取流程：文件 → 解密 → 返回
 *
 * 目录结构：
 * /data/secure/l1/  # 普通统计数据
 * /data/secure/l2/  # 生理趋势
 * /data/secure/l3/  # 原始特征（24h 销毁）
 * /data/secure/audit/ # 审计日志
 *
 * @module storage/secure-storage
 */

import { CryptoManager, CRYPTO_LEVEL } from '../privacy/crypto-manager'
import { Desensitizer } from '../privacy/desensitizer'

/**
 * 数据级别对应的存储目录
 */
const STORAGE_PATHS = {
  [CRYPTO_LEVEL.L1]: '/data/secure/l1/',
  [CRYPTO_LEVEL.L2]: '/data/secure/l2/',
  [CRYPTO_LEVEL.L3]: '/data/secure/l3/',
  audit: '/data/secure/audit/',
}

/**
 * 安全存储管理器
 */
export class SecureStorage {
  constructor() {
    this._cryptoManager = new CryptoManager()
    this._desensitizer = new Desensitizer()
    this._initialized = false
    this._deviceId = null
  }

  /**
   * 初始化安全存储
   *
   * @param {Object} params
   * @param {string} params.deviceId - 设备标识
   * @param {string} params.userPin - 用户 PIN
   * @returns {Promise<boolean>}
   */
  async init(params) {
    this._deviceId = params.deviceId
    await this._cryptoManager.init(params)

    // 确保存储目录存在
    await this._ensureDirectories()

    this._initialized = true
    return true
  }

  /**
   * 安全写入数据
   *
   * @param {Object} data - 原始数据
   * @param {number} level - 数据级别 (1, 2, 3)
   * @param {string} [filename] - 文件名（可选，自动生成）
   * @returns {Promise<Object>} 写入结果 { path, size, timestamp }
   */
  async write(data, level = CRYPTO_LEVEL.L1, filename = null) {
    this._checkInitialized()

    // 1. 脱敏检查
    const desensitized = this._desensitizer.desensitizeSensorData(data) ||
                         this._desensitizer.desensitizeEngineOutput(data)

    // 2. 加密
    const encrypted = await this._cryptoManager.encrypt(desensitized, level)

    // 3. 生成文件元数据
    const metadata = {
      filename: filename || this._generateFilename(level),
      level,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      size: 0,
      hash: await this._computeHash(encrypted),
    }

    // 4. 写入磁盘
    const path = STORAGE_PATHS[level] + metadata.filename
    const fileData = {
      metadata,
      payload: encrypted,
    }

    // 模拟文件系统写入（在 OpenVela 中使用 @system.file）
    await this._writeFile(path, JSON.stringify(fileData))

    metadata.size = JSON.stringify(fileData).length

    return {
      path,
      size: metadata.size,
      timestamp: metadata.createdAt,
    }
  }

  /**
   * 安全读取数据
   *
   * @param {string} path - 文件路径
   * @returns {Promise<Object>} 解密后的数据
   */
  async read(path) {
    this._checkInitialized()

    // 1. 读取文件
    const fileContent = await this._readFile(path)
    const fileData = JSON.parse(fileContent)

    // 2. 验证完整性
    const hash = await this._computeHash(fileData.payload)
    if (hash !== fileData.metadata.hash) {
      throw new Error('File integrity check failed')
    }

    // 3. 解密
    const decrypted = await this._cryptoManager.decrypt(fileData.payload)

    return decrypted
  }

  /**
   * 安全删除文件（覆写后删除）
   *
   * @param {string} path - 文件路径
   * @param {number} [overwriteTimes=3] - 覆写次数
   * @returns {Promise<boolean>}
   */
  async secureDelete(path, overwriteTimes = 3) {
    this._checkInitialized()

    // 覆写文件内容
    for (let i = 0; i < overwriteTimes; i++) {
      const noise = this._generateRandomBytes(1024)
      await this._writeFile(path, noise)
    }

    // 最终删除
    await this._deleteFile(path)

    return true
  }

  /**
   * 列出指定级别的所有文件
   *
   * @param {number} level - 数据级别
   * @returns {Promise<Array>} 文件元数据列表
   */
  async listFiles(level) {
    this._checkInitialized()

    const dirPath = STORAGE_PATHS[level] || STORAGE_PATHS.audit
    const files = await this._listDirectory(dirPath)

    return files.map(file => ({
      ...file,
      level,
    }))
  }

  /**
   * 获取存储统计信息
   *
   * @returns {Promise<Object>} { totalFiles, totalSize, byLevel }
   */
  async getStats() {
    this._checkInitialized()

    const stats = {
      totalFiles: 0,
      totalSize: 0,
      byLevel: {
        [CRYPTO_LEVEL.L1]: { count: 0, size: 0 },
        [CRYPTO_LEVEL.L2]: { count: 0, size: 0 },
        [CRYPTO_LEVEL.L3]: { count: 0, size: 0 },
        audit: { count: 0, size: 0 },
      },
    }

    for (const [levelKey, dirPath] of Object.entries(STORAGE_PATHS)) {
      const files = await this._listDirectory(dirPath)
      const levelStats = stats.byLevel[levelKey] || { count: 0, size: 0 }
      levelStats.count = files.length
      levelStats.size = files.reduce((sum, f) => sum + (f.size || 0), 0)
      stats.totalFiles += levelStats.count
      stats.totalSize += levelStats.size
    }

    return stats
  }

  /**
   * 确保存储目录存在
   *
   * @private
   */
  async _ensureDirectories() {
    for (const dirPath of Object.values(STORAGE_PATHS)) {
      await this._createDirectory(dirPath)
    }
  }

  /**
   * 生成文件名
   *
   * @param {number} level
   * @returns {string}
   * @private
   */
  _generateFilename(level) {
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(2, 8)
    return `l${level}_${timestamp}_${random}.enc`
  }

  /**
   * 计算数据哈希
   *
   * @param {Object} data
   * @returns {Promise<string>}
   * @private
   */
  async _computeHash(data) {
    const encoder = new TextEncoder()
    const dataBuffer = encoder.encode(JSON.stringify(data))
    const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer)
    const hashArray = Array.from(new Uint8Array(hashBuffer))
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('')
  }

  /**
   * 生成随机字节（用于覆写）
   *
   * @param {number} length
   * @returns {string}
   * @private
   */
  _generateRandomBytes(length) {
    const bytes = new Uint8Array(length)
    crypto.getRandomValues(bytes)
    return Array.from(bytes, b => String.fromCharCode(b)).join('')
  }

  /**
   * 检查是否已初始化
   * @private
   */
  _checkInitialized() {
    if (!this._initialized) {
      throw new Error('SecureStorage not initialized')
    }
  }

  // ============================================================
  // 以下为模拟文件系统操作（在 OpenVela 中替换为真实 API）
  // ============================================================

  /**
   * 写入文件（模拟）
   *
   * @param {string} path
   * @param {string} content
   * @private
   */
  async _writeFile(path, content) {
    // OpenVela: @system.file.write
    // 模拟实现：使用内存存储
    if (!this._mockFs) this._mockFs = {}
    this._mockFs[path] = content
    console.log(`[SecureStorage] Write: ${path} (${content.length} bytes)`)
  }

  /**
   * 读取文件（模拟）
   *
   * @param {string} path
   * @returns {Promise<string>}
   * @private
   */
  async _readFile(path) {
    // OpenVela: @system.file.read
    if (!this._mockFs || !this._mockFs[path]) {
      throw new Error(`File not found: ${path}`)
    }
    return this._mockFs[path]
  }

  /**
   * 删除文件（模拟）
   *
   * @param {string} path
   * @private
   */
  async _deleteFile(path) {
    // OpenVela: @system.file.delete
    if (this._mockFs) {
      delete this._mockFs[path]
    }
    console.log(`[SecureStorage] Deleted: ${path}`)
  }

  /**
   * 列出目录（模拟）
   *
   * @param {string} dirPath
   * @returns {Promise<Array>}
   * @private
   */
  async _listDirectory(dirPath) {
    // OpenVela: @system.file.list
    if (!this._mockFs) return []

    const files = []
    for (const path of Object.keys(this._mockFs)) {
      if (path.startsWith(dirPath)) {
        const filename = path.replace(dirPath, '')
        try {
          const content = this._mockFs[path]
          const fileData = JSON.parse(content)
          files.push({
            filename,
            path,
            size: content.length,
            createdAt: fileData.metadata?.createdAt || 0,
          })
        } catch {
          files.push({
            filename,
            path,
            size: content.length,
            createdAt: 0,
          })
        }
      }
    }
    return files
  }

  /**
   * 创建目录（模拟）
   *
   * @param {string} dirPath
   * @private
   */
  async _createDirectory(dirPath) {
    // OpenVela: @system.file.mkdir
    console.log(`[SecureStorage] Ensure dir: ${dirPath}`)
  }
}

export default SecureStorage

/**
 * 审计日志专用存储模块
 *
 * 实现安全审计日志的加密存储和防篡改机制：
 * - 每日一个日志文件，AES-256 加密
 * - 只追加模式，禁止修改历史日志
 * - 哈希链防篡改：每日文件生成 SHA-256 摘要，存储在次日文件头部
 *
 * @module storage/audit-store
 */

import { CryptoManager, CRYPTO_LEVEL } from '../privacy/crypto-manager'

/**
 * 审计日志存储路径
 */
const AUDIT_DIR = '/data/secure/audit/'

/**
 * 审计日志存储管理器
 */
export class AuditStore {
  constructor() {
    this._cryptoManager = null
    this._initialized = false
    // 内存缓冲区（当日日志）
    this._buffer = []
    // 当前日期标识
    this._currentDate = this._getDateKey()
    // 前一日哈希（用于哈希链）
    this._prevDayHash = null
  }

  /**
   * 初始化审计存储
   *
   * @param {CryptoManager} cryptoManager - 加密管理器实例
   * @returns {Promise<boolean>}
   */
  async init(cryptoManager) {
    this._cryptoManager = cryptoManager
    this._initialized = true

    // 加载前一日哈希
    await this._loadPrevDayHash()

    console.log('[AuditStore] Initialized')
    return true
  }

  /**
   * 追加审计日志条目
   *
   * @param {Object} entry - 日志条目
   * @param {string} entry.eventType - 事件类型
   * @param {string} entry.dataLevel - 数据级别
   * @param {string} entry.result - 结果
   * @param {Object} entry.details - 详情
   * @returns {Promise<boolean>}
   */
  async append(entry) {
    this._checkInitialized()

    const logEntry = {
      timestamp: Date.now(),
      eventType: entry.eventType || 'unknown',
      dataLevel: entry.dataLevel || 'none',
      result: entry.result || 'success',
      details: entry.details || {},
    }

    this._buffer.push(logEntry)

    // 检查是否需要切换日期文件
    const today = this._getDateKey()
    if (today !== this._currentDate) {
      await this._flushToDisk()
      this._currentDate = today
    }

    // 缓冲区满时自动刷盘
    if (this._buffer.length >= 100) {
      await this._flushToDisk()
    }

    return true
  }

  /**
   * 查询审计日志
   *
   * @param {number} startTime - 起始时间戳
   * @param {number} endTime - 结束时间戳
   * @returns {Promise<Array>} 日志条目列表
   */
  async queryLogs(startTime, endTime) {
    this._checkInitialized()

    const results = []
    const startKey = this._getDateKey(new Date(startTime))
    const endKey = this._getDateKey(new Date(endTime))

    // 遍历日期范围内的日志文件
    const files = await this._listAuditFiles()

    for (const file of files) {
      const fileDate = file.dateKey
      if (fileDate >= startKey && fileDate <= endKey) {
        const entries = await this._readLogFile(file)
        // 过滤时间范围
        for (const entry of entries) {
          if (entry.timestamp >= startTime && entry.timestamp <= endTime) {
            results.push(entry)
          }
        }
      }
    }

    // 合并内存缓冲区中的当日日志
    for (const entry of this._buffer) {
      if (entry.timestamp >= startTime && entry.timestamp <= endTime) {
        results.push(entry)
      }
    }

    // 按时间排序
    results.sort((a, b) => a.timestamp - b.timestamp)

    return results
  }

  /**
   * 刷盘：将缓冲区日志写入磁盘
   *
   * @returns {Promise<boolean>}
   */
  async flush() {
    return this._flushToDisk()
  }

  /**
   * 获取审计存储统计
   *
   * @returns {Promise<Object>}
   */
  async getStats() {
    const files = await this._listAuditFiles()
    let totalEntries = 0

    for (const file of files) {
      const entries = await this._readLogFile(file)
      totalEntries += entries.length
    }

    totalEntries += this._buffer.length

    return {
      totalFiles: files.length,
      totalEntries,
      bufferedEntries: this._buffer.length,
      currentFile: this._getLogFilePath(this._currentDate),
    }
  }

  /**
   * 将缓冲区写入磁盘
   *
   * @returns {Promise<boolean>}
   * @private
   */
  async _flushToDisk() {
    if (this._buffer.length === 0) return true

    const logData = {
      dateKey: this._currentDate,
      prevHash: this._prevDayHash,
      entries: [...this._buffer],
    }

    // 加密日志数据
    const encrypted = await this._cryptoManager.encrypt(logData, CRYPTO_LEVEL.L2)

    // 计算当日哈希（用于哈希链）
    const todayHash = await this._computeHash(encrypted)
    this._prevDayHash = todayHash

    // 写入文件
    const filePath = this._getLogFilePath(this._currentDate)
    const fileContent = JSON.stringify({
      hash: todayHash,
      payload: encrypted,
    })

    await this._writeFile(filePath, fileContent)

    // 清空缓冲区
    this._buffer = []

    console.log(`[AuditStore] Flushed ${logData.entries.length} entries to ${filePath}`)
    return true
  }

  /**
   * 读取日志文件并解密
   *
   * @param {Object} file - 文件信息
   * @returns {Promise<Array>} 日志条目列表
   * @private
   */
  async _readLogFile(file) {
    try {
      const content = await this._readFile(file.path)
      const fileData = JSON.parse(content)

      // 验证哈希链
      if (fileData.prevHash && this._prevDayHash) {
        // 实际应用中应验证哈希链完整性
      }

      // 解密
      const decrypted = await this._cryptoManager.decrypt(fileData.payload)
      return decrypted.entries || []
    } catch (error) {
      console.error(`[AuditStore] Failed to read log file: ${file.path}`, error)
      return []
    }
  }

  /**
   * 列出审计日志文件
   *
   * @returns {Promise<Array>}
   * @private
   */
  async _listAuditFiles() {
    // OpenVela: @system.file.list
    // 模拟实现
    if (!this._mockFs) return []

    const files = []
    for (const path of Object.keys(this._mockFs)) {
      if (path.startsWith(AUDIT_DIR) && path.endsWith('.enc')) {
        const filename = path.replace(AUDIT_DIR, '')
        const dateKey = filename.replace('audit_', '').replace('.enc', '')
        files.push({
          filename,
          path,
          dateKey,
        })
      }
    }

    return files.sort((a, b) => a.dateKey.localeCompare(b.dateKey))
  }

  /**
   * 加载前一日哈希
   *
   * @private
   */
  async _loadPrevDayHash() {
    const files = await this._listAuditFiles()
    if (files.length > 0) {
      const lastFile = files[files.length - 1]
      try {
        const content = await this._readFile(lastFile.path)
        const fileData = JSON.parse(content)
        this._prevDayHash = fileData.hash
      } catch {
        this._prevDayHash = null
      }
    }
  }

  /**
   * 获取日志文件路径
   *
   * @param {string} dateKey - 日期标识
   * @returns {string}
   * @private
   */
  _getLogFilePath(dateKey) {
    return `${AUDIT_DIR}audit_${dateKey}.enc`
  }

  /**
   * 获取日期标识
   *
   * @param {Date} [date]
   * @returns {string} YYYY-MM-DD 格式
   * @private
   */
  _getDateKey(date = new Date()) {
    return date.toISOString().split('T')[0]
  }

  /**
   * 计算数据哈希
   *
   * @param {Object} data
   * @returns {Promise<string>}
   * @private
   */
  async _computeHash(data) {
    const encoder = new TextEncoder()
    const dataBuffer = encoder.encode(JSON.stringify(data))
    const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer)
    const hashArray = Array.from(new Uint8Array(hashBuffer))
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('')
  }

  /**
   * 检查是否已初始化
   * @private
   */
  _checkInitialized() {
    if (!this._initialized) {
      throw new Error('AuditStore not initialized')
    }
  }

  // ============================================================
  // 模拟文件系统操作（OpenVela 中替换为真实 API）
  // ============================================================

  async _writeFile(path, content) {
    if (!this._mockFs) this._mockFs = {}
    this._mockFs[path] = content
    console.log(`[AuditStore] Write: ${path}`)
  }

  async _readFile(path) {
    if (!this._mockFs || !this._mockFs[path]) {
      throw new Error(`File not found: ${path}`)
    }
    return this._mockFs[path]
  }
}

export default AuditStore

/**
 * 安全审计日志模块
 *
 * 记录所有数据访问、加密、解密、销毁事件。
 * 所有日志通过 AuditStore 加密存储，支持哈希链防篡改。
 *
 * 事件类型：
 * - DATA_ACCESS: 数据读取访问
 * - DATA_WRITE: 数据写入
 * - DATA_DELETE: 数据删除
 * - DATA_DESSENSITIZE: 数据脱敏处理
 * - ENCRYPT: 加密操作
 * - DECRYPT: 解密操作
 * - KEY_DERIVE: 密钥派生
 * - KEY_SHARD: 密钥分片
 * - LIFECYCLE_TRANSFER: 生命周期状态转移
 * - LIFECYCLE_DESTROY: 数据销毁
 * - ALERT_TRIGGER: 提醒触发
 *
 * @module privacy/audit-logger
 */

import { AuditStore } from '../storage/audit-store'

/**
 * 事件类型枚举
 */
export const AUDIT_EVENT = {
  DATA_ACCESS: 'data_access',
  DATA_WRITE: 'data_write',
  DATA_DELETE: 'data_delete',
  DATA_DESSENSITIZE: 'data_desensitize',
  ENCRYPT: 'encrypt',
  DECRYPT: 'decrypt',
  KEY_DERIVE: 'key_derive',
  KEY_SHARD: 'key_shard',
  LIFECYCLE_TRANSFER: 'lifecycle_transfer',
  LIFECYCLE_DESTROY: 'lifecycle_destroy',
  ALERT_TRIGGER: 'alert_trigger',
}

/**
 * 安全审计日志管理器
 */
export class AuditLogger {
  constructor() {
    this._store = new AuditStore()
    this._initialized = false
    // 内存缓冲区（用于高频事件聚合）
    this._recentEvents = []
    this._maxRecentEvents = 50
  }

  /**
   * 初始化审计日志
   *
   * @param {CryptoManager} cryptoManager - 加密管理器
   * @returns {Promise<boolean>}
   */
  async init(cryptoManager) {
    await this._store.init(cryptoManager)
    this._initialized = true

    // 记录初始化事件
    await this.log(AUDIT_EVENT.DATA_ACCESS, 'system', 'initialized', {
      message: 'AuditLogger initialized',
    })

    return true
  }

  /**
   * 记录审计事件
   *
   * @param {string} eventType - 事件类型
   * @param {string} dataLevel - 数据级别 (l1, l2, l3, system)
   * @param {string} result - 结果 (success, failure, denied)
   * @param {Object} [details] - 详情
   * @returns {Promise<boolean>}
   */
  async log(eventType, dataLevel, result, details = {}) {
    if (!this._initialized) {
      console.warn('[AuditLogger] Not initialized, event dropped')
      return false
    }

    // 添加到最近事件列表
    this._recentEvents.unshift({
      timestamp: Date.now(),
      eventType,
      dataLevel,
      result,
      details,
    })

    // 限制内存缓冲大小
    if (this._recentEvents.length > this._maxRecentEvents) {
      this._recentEvents.pop()
    }

    // 写入持久化存储
    return this._store.append({
      eventType,
      dataLevel,
      result,
      details: {
        ...details,
        source: 'audit-logger',
      },
    })
  }

  /**
   * 记录数据访问事件
   *
   * @param {string} path - 数据路径
   * @param {string} level - 数据级别
   * @param {string} result - 结果
   * @param {Object} [details]
   */
  async logAccess(path, level, result, details = {}) {
    return this.log(AUDIT_EVENT.DATA_ACCESS, level, result, {
      path,
      ...details,
    })
  }

  /**
   * 记录数据写入事件
   *
   * @param {string} path - 数据路径
   * @param {string} level - 数据级别
   * @param {number} size - 数据大小
   * @param {Object} [details]
   */
  async logWrite(path, level, size, details = {}) {
    return this.log(AUDIT_EVENT.DATA_WRITE, level, 'success', {
      path,
      size,
      ...details,
    })
  }

  /**
   * 记录数据删除事件
   *
   * @param {string} path - 数据路径
   * @param {string} level - 数据级别
   * @param {string} reason - 删除原因
   */
  async logDelete(path, level, reason) {
    return this.log(AUDIT_EVENT.DATA_DELETE, level, 'success', {
      path,
      reason,
    })
  }

  /**
   * 记录脱敏处理事件
   *
   * @param {string} dataType - 数据类型
   * @param {Object} rules - 应用的脱敏规则
   */
  async logDesensitize(dataType, rules) {
    return this.log(AUDIT_EVENT.DATA_DESSENSITIZE, 'system', 'success', {
      dataType,
      rules: Object.keys(rules),
    })
  }

  /**
   * 记录加密事件
   *
   * @param {string} level - 加密级别
   * @param {string} algorithm - 算法
   * @param {Object} [details]
   */
  async logEncrypt(level, algorithm, details = {}) {
    return this.log(AUDIT_EVENT.ENCRYPT, level, 'success', {
      algorithm,
      ...details,
    })
  }

  /**
   * 记录解密事件
   *
   * @param {string} level - 加密级别
   * @param {string} result - 结果
   * @param {Object} [details]
   */
  async logDecrypt(level, result, details = {}) {
    return this.log(AUDIT_EVENT.DECRYPT, level, result, details)
  }

  /**
   * 记录数据销毁事件
   *
   * @param {string} path - 数据路径
   * @param {string} level - 数据级别
   * @param {string} reason - 销毁原因
   */
  async logDestroy(path, level, reason) {
    return this.log(AUDIT_EVENT.LIFECYCLE_DESTROY, level, 'success', {
      path,
      reason,
      destroyMethod: 'overwrite_zero',
    })
  }

  /**
   * 记录生命周期状态转移
   *
   * @param {string} path - 数据路径
   * @param {string} fromState - 原状态
   * @param {string} toState - 新状态
   */
  async logLifecycleTransfer(path, fromState, toState) {
    return this.log(AUDIT_EVENT.LIFECYCLE_TRANSFER, 'system', 'success', {
      path,
      fromState,
      toState,
    })
  }

  /**
   * 查询审计日志
   *
   * @param {number} startTime - 起始时间戳
   * @param {number} endTime - 结束时间戳
   * @returns {Promise<Array>} 日志条目列表
   */
  async queryLogs(startTime, endTime) {
    return this._store.queryLogs(startTime, endTime)
  }

  /**
   * 获取最近的事件（内存中）
   *
   * @param {number} [count=20] - 获取条数
   * @returns {Array}
   */
  getRecentEvents(count = 20) {
    return this._recentEvents.slice(0, count)
  }

  /**
   * 获取统计信息
   *
   * @returns {Promise<Object>}
   */
  async getStats() {
    const storeStats = await this._store.getStats()

    // 统计事件类型分布
    const eventTypeCounts = {}
    for (const event of this._recentEvents) {
      eventTypeCounts[event.eventType] = (eventTypeCounts[event.eventType] || 0) + 1
    }

    return {
      ...storeStats,
      recentEventTypes: eventTypeCounts,
    }
  }

  /**
   * 刷新缓冲区到磁盘
   *
   * @returns {Promise<boolean>}
   */
  async flush() {
    return this._store.flush()
  }
}

export default AuditLogger

/**
 * 数据生命周期管理模块
 *
 * 实现数据四级状态机：
 * - 热数据：24小时内，内存缓存，快速访问
 * - 温数据：1-7天，AES-128 存储
 * - 冷数据：7-30天，AES-256 + 压缩存储
 * - 销毁：30天后覆写清零
 *
 * L3 数据特殊规则：24小时强制销毁，不可配置
 *
 * @module privacy/lifecycle-manager
 */

import { AuditLogger, AUDIT_EVENT } from './audit-logger'

/**
 * 数据生命周期状态
 */
export const LIFECYCLE_STATE = {
  HOT: 'hot',       // 热数据：24小时内
  WARM: 'warm',     // 温数据：1-7天
  COLD: 'cold',     // 冷数据：7-30天
  DESTROY: 'destroy', // 待销毁
}

/**
 * 生命周期配置（毫秒）
 */
const LIFECYCLE_CONFIG = {
  [LIFECYCLE_STATE.HOT]: {
    maxAge: 24 * 60 * 60 * 1000,  // 24小时
    nextState: LIFECYCLE_STATE.WARM,
    storageLevel: 1,  // AES-128
  },
  [LIFECYCLE_STATE.WARM]: {
    maxAge: 7 * 24 * 60 * 60 * 1000,  // 7天
    nextState: LIFECYCLE_STATE.COLD,
    storageLevel: 1,  // AES-128
  },
  [LIFECYCLE_STATE.COLD]: {
    maxAge: 30 * 24 * 60 * 60 * 1000,  // 30天
    nextState: LIFECYCLE_STATE.DESTROY,
    storageLevel: 2,  // AES-256
  },
  [LIFECYCLE_STATE.DESTROY]: {
    maxAge: 0,  // 立即销毁
    nextState: null,
    storageLevel: null,
  },
}

/**
 * L3 数据特殊配置：24小时强制销毁
 */
const L3_CONFIG = {
  maxAge: 24 * 60 * 60 * 1000,  // 24小时
  forceDestroy: true,
  storageLevel: 3,
}

/**
 * 数据生命周期管理器
 */
export class LifecycleManager {
  constructor() {
    this._auditLogger = null
    this._storageManager = null
    this._initialized = false

    // 内存中的热数据缓存
    this._hotCache = new Map()

    // 文件元数据索引 { path: { state, createdAt, level, size } }
    this._metadataIndex = new Map()

    // 清理任务定时器
    this._cleanupTimer = null
  }

  /**
   * 初始化生命周期管理器
   *
   * @param {Object} params
   * @param {AuditLogger} params.auditLogger - 审计日志
   * @param {Object} params.storageManager - 存储管理器
   * @returns {Promise<boolean>}
   */
  async init(params) {
    this._auditLogger = params.auditLogger
    this._storageManager = params.storageManager
    this._initialized = true

    // 扫描现有文件，建立元数据索引
    await this._scanExistingFiles()

    // 启动清理任务
    this._startCleanupTask()

    // 执行一次初始清理
    await this._runCleanup()

    return true
  }

  /**
   * 注册新数据到生命周期管理
   *
   * @param {Object} params
   * @param {string} params.path - 文件路径
   * @param {number} params.level - 数据级别 (1, 2, 3)
   * @param {number} params.size - 数据大小
   * @returns {Promise<Object>} 初始状态信息
   */
  async register(params) {
    this._checkInitialized()

    const { path, level, size } = params
    const now = Date.now()

    // L3 数据特殊处理
    if (level === 3) {
      const metadata = {
        path,
        level,
        state: LIFECYCLE_STATE.HOT,
        createdAt: now,
        updatedAt: now,
        size,
        isL3: true,
        destroyAt: now + L3_CONFIG.maxAge,
      }
      this._metadataIndex.set(path, metadata)

      await this._auditLogger.logLifecycleTransfer(path, 'new', LIFECYCLE_STATE.HOT)

      return metadata
    }

    // 普通数据
    const metadata = {
      path,
      level,
      state: LIFECYCLE_STATE.HOT,
      createdAt: now,
      updatedAt: now,
      size,
      isL3: false,
    }
    this._metadataIndex.set(path, metadata)

    // 添加到热缓存
    this._hotCache.set(path, { data: null, metadata })

    await this._auditLogger.logLifecycleTransfer(path, 'new', LIFECYCLE_STATE.HOT)

    return metadata
  }

  /**
   * 获取数据（自动处理生命周期）
   *
   * @param {string} path - 文件路径
   * @returns {Promise<Object|null>} 数据内容
   */
  async get(path) {
    this._checkInitialized()

    const metadata = this._metadataIndex.get(path)
    if (!metadata) {
      await this._auditLogger.logAccess(path, 'unknown', 'not_found')
      return null
    }

    // 检查是否已过期
    if (this._isExpired(metadata)) {
      await this._destroy(path, metadata)
      return null
    }

    // 从热缓存读取
    if (metadata.state === LIFECYCLE_STATE.HOT) {
      const cached = this._hotCache.get(path)
      if (cached && cached.data) {
        await this._auditLogger.logAccess(path, `l${metadata.level}`, 'success', {
          source: 'hot_cache',
        })
        return cached.data
      }
    }

    // 从存储读取
    try {
      const data = await this._storageManager.read(path)
      await this._auditLogger.logAccess(path, `l${metadata.level}`, 'success', {
        source: 'storage',
        state: metadata.state,
      })
      return data
    } catch (error) {
      await this._auditLogger.logAccess(path, `l${metadata.level}`, 'failure', {
        error: error.message,
      })
      return null
    }
  }

  /**
   * 执行生命周期清理
   *
   * @returns {Promise<Object>} 清理统计
   */
  async runCleanup() {
    return this._runCleanup()
  }

  /**
   * 获取生命周期统计
   *
   * @returns {Object}
   */
  getStats() {
    const stats = {
      total: this._metadataIndex.size,
      byState: {
        [LIFECYCLE_STATE.HOT]: 0,
        [LIFECYCLE_STATE.WARM]: 0,
        [LIFECYCLE_STATE.COLD]: 0,
        [LIFECYCLE_STATE.DESTROY]: 0,
      },
      byLevel: {
        1: 0,
        2: 0,
        3: 0,
      },
      hotCacheSize: this._hotCache.size,
      totalSize: 0,
    }

    for (const metadata of this._metadataIndex.values()) {
      stats.byState[metadata.state]++
      stats.byLevel[metadata.level]++
      stats.totalSize += metadata.size || 0
    }

    return stats
  }

  /**
   * 销毁所有数据（紧急情况）
   *
   * @returns {Promise<number>} 销毁的文件数量
   */
  async destroyAll() {
    let count = 0
    for (const [path, metadata] of this._metadataIndex.entries()) {
      await this._destroy(path, metadata)
      count++
    }
    this._hotCache.clear()
    return count
  }

  /**
   * 执行清理任务
   *
   * @returns {Promise<Object>}
   * @private
   */
  async _runCleanup() {
    const now = Date.now()
    const stats = {
      scanned: 0,
      transferred: 0,
      destroyed: 0,
    }

    for (const [path, metadata] of this._metadataIndex.entries()) {
      stats.scanned++

      const age = now - metadata.createdAt

      // L3 数据特殊处理：24小时强制销毁
      if (metadata.isL3) {
        if (age >= L3_CONFIG.maxAge) {
          await this._destroy(path, metadata)
          stats.destroyed++
        }
        continue
      }

      // 普通数据状态转移
      const currentState = metadata.state
      const config = LIFECYCLE_CONFIG[currentState]

      if (age >= config.maxAge && config.nextState) {
        if (config.nextState === LIFECYCLE_STATE.DESTROY) {
          await this._destroy(path, metadata)
          stats.destroyed++
        } else {
          await this._transfer(path, metadata, config.nextState)
          stats.transferred++
        }
      }
    }

    // 记录清理审计
    await this._auditLogger.log(AUDIT_EVENT.LIFECYCLE_TRANSFER, 'system', 'success', {
      action: 'cleanup',
      ...stats,
    })

    return stats
  }

  /**
   * 转移数据状态
   *
   * @param {string} path
   * @param {Object} metadata
   * @param {string} newState
   * @private
   */
  async _transfer(path, metadata, newState) {
    const oldState = metadata.state
    const newConfig = LIFECYCLE_CONFIG[newState]

    // 更新元数据
    metadata.state = newState
    metadata.updatedAt = Date.now()
    metadata.level = newConfig.storageLevel

    // 从热缓存移除（如果不在热状态）
    if (oldState === LIFECYCLE_STATE.HOT) {
      this._hotCache.delete(path)
    }

    await this._auditLogger.logLifecycleTransfer(path, oldState, newState)

    console.log(`[Lifecycle] Transferred: ${path} from ${oldState} to ${newState}`)
  }

  /**
   * 销毁数据
   *
   * @param {string} path
   * @param {Object} metadata
   * @private
   */
  async _destroy(path, metadata) {
    // 从缓存移除
    this._hotCache.delete(path)

    // 安全删除文件
    try {
      await this._storageManager.secureDelete(path, 3)
    } catch (error) {
      console.error(`[Lifecycle] Failed to delete file: ${path}`, error)
    }

    // 记录销毁审计
    await this._auditLogger.logDestroy(path, `l${metadata.level}`, metadata.isL3 ? 'l3_expire' : 'age_expire')

    // 从索引移除
    this._metadataIndex.delete(path)

    console.log(`[Lifecycle] Destroyed: ${path}`)
  }

  /**
   * 检查数据是否过期
   *
   * @param {Object} metadata
   * @returns {boolean}
   * @private
   */
  _isExpired(metadata) {
    const now = Date.now()
    const age = now - metadata.createdAt

    if (metadata.isL3) {
      return age >= L3_CONFIG.maxAge
    }

    const config = LIFECYCLE_CONFIG[metadata.state]
    return age >= config.maxAge
  }

  /**
   * 扫描现有文件建立索引
   *
   * @private
   */
  async _scanExistingFiles() {
    // 扫描各级别目录
    for (const level of [1, 2, 3]) {
      try {
        const files = await this._storageManager.listFiles(level)
        for (const file of files) {
          if (!this._metadataIndex.has(file.path)) {
            const age = Date.now() - (file.createdAt || Date.now())
            let state = LIFECYCLE_STATE.HOT

            if (file.level === 3 && age >= L3_CONFIG.maxAge) {
              // L3 已过期，待销毁
              state = LIFECYCLE_STATE.DESTROY
            } else if (age >= LIFECYCLE_CONFIG[LIFECYCLE_STATE.COLD].maxAge) {
              state = LIFECYCLE_STATE.COLD
            } else if (age >= LIFECYCLE_CONFIG[LIFECYCLE_STATE.WARM].maxAge) {
              state = LIFECYCLE_STATE.WARM
            }

            this._metadataIndex.set(file.path, {
              path: file.path,
              level: file.level,
              state,
              createdAt: file.createdAt || Date.now(),
              updatedAt: file.createdAt || Date.now(),
              size: file.size || 0,
              isL3: file.level === 3,
            })
          }
        }
      } catch (error) {
        console.warn(`[Lifecycle] Failed to scan level ${level}:`, error)
      }
    }
  }

  /**
   * 启动清理任务定时器
   * 每日 00:00 执行清理（或启动时检查）
   *
   * @private
   */
  _startCleanupTask() {
    // 计算距下一个 00:00 的毫秒数
    const now = new Date()
    const nextMidnight = new Date(now)
    nextMidnight.setHours(24, 0, 0, 0)
    const msUntilMidnight = nextMidnight.getTime() - now.getTime()

    // 首次在午夜执行
    setTimeout(() => {
      this._runCleanup()
      // 之后每 24 小时执行一次
      this._cleanupTimer = setInterval(() => {
        this._runCleanup()
      }, 24 * 60 * 60 * 1000)
    }, msUntilMidnight)
  }

  /**
   * 停止清理任务
   */
  stop() {
    if (this._cleanupTimer) {
      clearInterval(this._cleanupTimer)
      this._cleanupTimer = null
    }
  }

  /**
   * 检查是否已初始化
   * @private
   */
  _checkInitialized() {
    if (!this._initialized) {
      throw new Error('LifecycleManager not initialized')
    }
  }
}

export default LifecycleManager

