290	    this.gyroDriver.startSampling(sensorConfig)
291	    this.hrDriver.startSampling({ ...sensorConfig, strategy: 'static' })
292	
293	    // 连接传感器到引擎
294	    this.engine.sensorInterface = {
295	      onData: (callback) => {
296	        this.accDriver.onData((data) => {
297	          if (callback) callback(data)
298	        })
299	        this.gyroDriver.onData((data) => {
300	          if (callback) callback(data)
301	        })
302	      },
303	    }
