357	    this.severity = filterResult.severity
358	    this.duration = Math.round(filterResult.duration)
359	    this.confirmed = filterResult.confirmed
360	
361	    // 更新详情
362	    if (filterResult.confirmed) {
363	      this.postureDetail = `⚠️ ${filterResult.detail}`
364	    } else if (filterResult.posture !== POSTURE_TYPE.NORMAL) {
365	      this.postureDetail = `检测中: ${filterResult.detail}`
366	    } else {
367	      this.postureDetail = '体态正常'
368	    }
